/* Index de recherche globale — généré par tools/indexer.js.
   Ne pas modifier à la main : relancez le script après tout ajout. */
var INDEX_GLOBAL = [{"n":"Étape 1 — Les dix premières minutes","c":"Parcours","p":"parcours.html","a":"p01","d":"Passer des mains nues à un jeu d'outils en pierre. L'étape est finie quand vous avez pioche, hache et épée en pierre, un four, et une pile d"},{"n":"Étape 2 — Survivre à la première nuit","c":"Parcours","p":"parcours.html","a":"p02","d":"Ne pas mourir et fixer un point de réapparition. C'est gagné quand vous vous réveillez au matin dans un abri fermé, avec un lit posé et un c"},{"n":"Étape 3 — Le premier fer","c":"Parcours","p":"parcours.html","a":"p03","d":"Sortir de l'âge de pierre. L'étape est atteinte quand vous portez une armure de fer complète et que vous avez un seau, un bouclier et une pi"},{"n":"Étape 4 — Manger sans y penser","c":"Parcours","p":"parcours.html","a":"p04","d":"Supprimer définitivement la question de la nourriture. C'est réglé quand vous produisez plus que vous ne consommez, sans y penser."},{"n":"Étape 5 — Bâtir la vraie base","c":"Parcours","p":"parcours.html","a":"p05","d":"Remplacer le trou de survie par un atelier. L'étape est finie quand tous vos postes de travail sont réunis au même endroit avec un mur de co"},{"n":"Étape 6 — Les premières automatisations","c":"Parcours","p":"parcours.html","a":"p06","d":"Arrêter de fabriquer à la main ce que le jeu produit seul. C'est atteint quand carburant, pierre et bois arrivent dans un coffre sans que vo"},{"n":"Étape 7 — Le village et le commerce","c":"Parcours","p":"parcours.html","a":"p07","d":"Transformer les émeraudes en raccourci permanent. C'est atteint quand un bibliothécaire vous vend Raccommodage et qu'un autre villageois ach"},{"n":"Étape 8 — Descendre au diamant","c":"Parcours","p":"parcours.html","a":"p08","d":"Ramener de quoi tailler une pioche en diamant et une table d'enchantement. C'est fini quand vous avez au moins 10 diamants, 30 lapis et une "},{"n":"Étape 9 — La table niveau 30","c":"Parcours","p":"parcours.html","a":"p09","d":"Pouvoir lancer des enchantements de niveau 30 à volonté. C'est atteint quand la table affiche 30 et qu'un stock de lapis permet de relancer "},{"n":"Étape 10 — Une ferme à XP qui tourne","c":"Parcours","p":"parcours.html","a":"p10","d":"Ne plus jamais manquer de niveaux. L'étape est finie quand vous remontez de 0 à 30 en moins de dix minutes sans quitter votre base."},{"n":"Étape 11 — L'équipement avant le Nether","c":"Parcours","p":"parcours.html","a":"p11","d":"Partir dans le Nether avec du matériel qui pardonne les erreurs. C'est prêt quand votre armure est enchantée et qu'un jeu de secours dort da"},{"n":"Étape 12 — Ouvrir et sécuriser le portail","c":"Parcours","p":"parcours.html","a":"p12","d":"Entrer dans le Nether et pouvoir en ressortir à coup sûr. L'étape est réussie quand l'arrivée est enfermée dans une salle close et signalée "},{"n":"Étape 13 — La forteresse du Nether","c":"Parcours","p":"parcours.html","a":"p13","d":"Ramener les bâtons de Blaze et la verrue du Nether. Sans eux il n'y a ni potion ni œil de l'Ender ; c'est fait quand un alambic peut être po"},{"n":"Étape 14 — Bastion, or et débris antiques","c":"Parcours","p":"parcours.html","a":"p14","d":"Ramener de quoi passer à la netherite. L'étape est atteinte quand vous avez le modèle de forge d'amélioration et au moins 4 débris antiques."},{"n":"Étape 15 — Passer à la netherite","c":"Parcours","p":"parcours.html","a":"p15","d":"Mettre l'équipement critique à l'abri du feu et de la perte. C'est fait quand pioche et plastron flottent sur la lave au lieu de brûler."},{"n":"Étape 16 — Ouvrir l'atelier de brassage","c":"Parcours","p":"parcours.html","a":"p16","d":"Avoir des potions sous la main en permanence. C'est en place quand un coffre contient Résistance au feu, Vision nocturne et Force sans que v"},{"n":"Étape 17 — Les yeux et la forteresse","c":"Parcours","p":"parcours.html","a":"p17","d":"Trouver le portail de l'End et l'allumer. C'est fait quand les 12 cadres sont pourvus et que le vide étoilé apparaît sous vos pieds."},{"n":"Étape 18 — Le dragon de l'Ender","c":"Parcours","p":"parcours.html","a":"p18","d":"Abattre le dragon. C'est terminé quand le portail de sortie s'ouvre et que la passerelle vers les îles extérieures apparaît."},{"n":"Étape 19 — Ramener l'élytre","c":"Parcours","p":"parcours.html","a":"p19","d":"Obtenir une élytre. C'est réussi quand vous décollez à la fusée depuis votre base et traversez la carte sans toucher le sol."},{"n":"Étape 20 — Les boîtes de shulker","c":"Parcours","p":"parcours.html","a":"p20","d":"Régler le problème de l'inventaire une fois pour toutes. C'est atteint quand vous transportez un chantier entier en une seule fournée."},{"n":"Étape 21 — Les fermes de production","c":"Parcours","p":"parcours.html","a":"p21","d":"Faire produire la base pendant que vous jouez ailleurs. C'est en place quand fer, or et émeraudes s'accumulent sans que vous y touchiez."},{"n":"Étape 22 — Tri automatique et réseau","c":"Parcours","p":"parcours.html","a":"p22","d":"Ne plus ranger à la main ni voyager à pied. C'est fini quand vider son inventaire prend un clic et rejoindre n'importe quel point de la cart"},{"n":"Étape 23 — Balise et conduit","c":"Parcours","p":"parcours.html","a":"p23","d":"Installer les effets permanents. C'est atteint quand Hâte II couvre votre zone de chantier et qu'un conduit rend l'eau respirable autour du "},{"n":"Étape 24 — Les grands chantiers","c":"Parcours","p":"parcours.html","a":"p24","d":"Se servir de tout ce qui précède pour construire ce qui vous plaît. Il n'y a plus de condition de sortie, seulement des projets."},{"n":"Faim et saturation","c":"Mécanique","p":"mecaniques.html","d":"La barre de faim compte 20 points, mais chaque aliment remplit aussi une réserve invisible — la saturation — qui se vide en premier."},{"n":"Régénération des points de vie","c":"Mécanique","p":"mecaniques.html","d":"La vie ne remonte pas toute seule : elle est payée en nourriture, et à deux vitesses très différentes."},{"n":"Dégâts de chute","c":"Mécanique","p":"mecaniques.html","d":"La hauteur tue plus de joueurs que les monstres, et la règle est parfaitement linéaire."},{"n":"Noyade et réserve d'air","c":"Mécanique","p":"mecaniques.html","d":"Sous l'eau, la barre de bulles est un compte à rebours ; une fois vide, les dégâts sont réguliers et l'armure n'y change rien."},{"n":"Feu et lave","c":"Mécanique","p":"mecaniques.html","d":"Brûler fait des dégâts modérés mais continus ; la lave, elle, tue en quelques secondes et détruit tout l'inventaire au passage."},{"n":"Ce que les effets font à la barre de vie","c":"Mécanique","p":"mecaniques.html","d":"Absorption, Poison, Wither et Résistance agissent tous sur la vie, mais aucun de la même façon."},{"n":"Sommeil et point de réapparition","c":"Mécanique","p":"mecaniques.html","d":"Le lit fait trois choses distinctes : passer la nuit, arrêter la météo et enregistrer un point de réapparition."},{"n":"Mort : objets au sol et expérience","c":"Mécanique","p":"mecaniques.html","d":"À la mort, l'inventaire tombe sur place et un compte à rebours démarre. Ce qu'on récupère dépend surtout de la vitesse de retour."},{"n":"Difficulté du monde","c":"Mécanique","p":"mecaniques.html","d":"Le curseur de difficulté change les dégâts subis et quelques comportements de monstres — pas le nombre de mobs ni le butin."},{"n":"Délai de rechargement d'attaque","c":"Mécanique","p":"mecaniques.html","d":"Depuis la 1.9, chaque arme a une cadence. Frapper avant la fin du rechargement divise les dégâts."},{"n":"Coup critique et coup balayant","c":"Mécanique","p":"mecaniques.html","d":"Deux bonus gratuits, chacun avec des conditions strictes — et une condition commune : ne pas sprinter."},{"n":"Invincibilité d'une demi-seconde","c":"Mécanique","p":"mecaniques.html","d":"Après chaque dégât reçu, joueur comme mob devient brièvement insensible. Toute la tactique de combat en découle."},{"n":"Armure et ténacité","c":"Mécanique","p":"mecaniques.html","d":"L'armure réduit un pourcentage des dégâts, mais cette réduction fond quand le coup encaissé est énorme. C'est là qu'intervient la ténacité."},{"n":"Boucliers et haches","c":"Mécanique","p":"mecaniques.html","d":"Un bouclier levé annule totalement les dégâts venant de face — mais il s'arme avec un temps de retard et une hache le neutralise."},{"n":"Recul","c":"Mécanique","p":"mecaniques.html","d":"Le recul déplace la cible — et vous aussi. C'est un outil de survie, et une plaie dès qu'on veut garder un mob en place."},{"n":"Ce qui décide un mob à vous attaquer","c":"Mécanique","p":"mecaniques.html","d":"Chaque famille de monstres a son propre déclencheur : la vue, le regard, l'or que vous portez ou le coup que vous venez de donner."},{"n":"Niveau de lumière et apparition des monstres","c":"Mécanique","p":"mecaniques.html","d":"Dans l'Overworld, la règle est devenue binaire : un monstre a besoin d'un niveau de lumière de bloc égal à 0 pour apparaître."},{"n":"Distances d'apparition et de disparition","c":"Mécanique","p":"mecaniques.html","d":"Les monstres n'apparaissent que dans une couronne autour de vous, et disparaissent selon leur éloignement. Toute ferme à mobs se conçoit à p"},{"n":"Cycle jour/nuit","c":"Mécanique","p":"mecaniques.html","d":"Une journée complète dure 24 000 ticks, soit 20 minutes réelles. C'est l'unité de temps la plus utile pour planifier."},{"n":"Météo et orages","c":"Mécanique","p":"mecaniques.html","d":"La pluie gêne un peu ; l'orage, lui, change les règles d'apparition en plein jour et ouvre une fenêtre unique."},{"n":"Propagation du feu","c":"Mécanique","p":"mecaniques.html","d":"Le feu ne se propage qu'à des blocs inflammables, mais il monte bien plus loin qu'il ne s'étale."},{"n":"Blocs soumis à la gravité","c":"Mécanique","p":"mecaniques.html","d":"Quelques blocs tombent dès que leur support disparaît. C'est un danger en mine et un outil de chantier."},{"n":"Cultures : lumière, hydratation, croissance","c":"Mécanique","p":"mecaniques.html","d":"Une culture pousse par à-coups, quand le hasard la désigne. Les seuls leviers sont l'eau, la lumière et le nombre de plants."},{"n":"Propagation de l'eau et de la lave","c":"Mécanique","p":"mecaniques.html","d":"Les deux fluides suivent la même logique de niveaux décroissants, avec des portées et des vitesses très différentes."},{"n":"Expérience et coût des niveaux","c":"Mécanique","p":"mecaniques.html","d":"La barre d'XP n'est pas linéaire : chaque niveau coûte plus cher que le précédent, et l'enchantement n'en consomme qu'une fraction."},{"n":"Enclume : la pénalité de travail","c":"Mécanique","p":"mecaniques.html","d":"Chaque passage à l'enclume marque l'objet. Au bout de quelques opérations, il devient définitivement impossible à modifier en survie."},{"n":"Difficulté régionale","c":"Mécanique","p":"mecaniques.html","d":"Une valeur invisible, calculée par chunk, qui monte avec le temps que vous y passez et rend les monstres du coin progressivement plus danger"},{"n":"Phantoms et compteur de sommeil","c":"Mécanique","p":"mecaniques.html","d":"Les phantoms ne sont pas un mob de plus : ils sont un rappel programmé, déclenché par un compteur personnel."},{"n":"Ticks : le rythme du jeu","c":"Mécanique","p":"mecaniques.html","d":"Tout le jeu avance par pas de 0,05 seconde. Les circuits de redstone, eux, comptent en pas de 0,1 seconde."},{"n":"Limite d'entités (mob cap)","c":"Mécanique","p":"mecaniques.html","d":"Le jeu plafonne le nombre de créatures existant simultanément autour de vous. Quand le quota est plein, plus rien n'apparaît nulle part."},{"n":"Chunks, simulation et chargement","c":"Mécanique","p":"mecaniques.html","d":"Le monde est découpé en colonnes de 16 × 16 blocs. Seules celles qui sont simulées font tourner quoi que ce soit."},{"n":"Le hasard des tirages de butin","c":"Mécanique","p":"mecaniques.html","d":"Coffres, mobs et pêche tirent dans des listes pondérées. Comprendre quand le tirage a lieu évite beaucoup de temps perdu."},{"n":"Zombie","c":"Drops","p":"drops.html","d":"Partout où la lumière du bloc est à 0 : surface la nuit, grottes, donjons. Apparaît aussi dans les villages (siège de zombies) et via les gé"},{"n":"Squelette","c":"Drops","p":"drops.html","d":"Zones sombres du Surworld, grottes, donjons, générateurs. Dans le Nether : forteresses (withers squelettes)."},{"n":"Creeper","c":"Drops","p":"drops.html","d":"Zones sombres, ne brûle pas au soleil : on en croise donc en plein jour. Jamais dans les donjons via générateur."},{"n":"Araignée","c":"Drops","p":"drops.html","d":"Zones sombres, grottes, mines abandonnées (araignée venimeuse via cocons). Neutre en pleine lumière."},{"n":"Enderman","c":"Drops","p":"drops.html","d":"Lumière ≤ 7 dans le Surworld, très fréquent dans les plaines de l'End et dans les vallées de sable des âmes / forêts déformées du Nether."},{"n":"Sorcière","c":"Drops","p":"drops.html","d":"Zones sombres, huttes de marais (avec un chat noir), raids de pillards."},{"n":"Noyé (Drowned)","c":"Drops","p":"drops.html","d":"Océans, rivières, grottes aquatiques (Y ≤ 58). Un zombie qui se noie 30 s se transforme en noyé."},{"n":"Momifié (Husk)","c":"Drops","p":"drops.html","d":"Déserts, à n'importe quelle heure — il ne brûle pas au soleil."},{"n":"Vagabond (Stray)","c":"Drops","p":"drops.html","d":"Plaines enneigées, pics glacés, toundra — à ciel ouvert."},{"n":"Embourbé (Bogged)","c":"Drops","p":"drops.html","d":"Marais, marais de mangrove, et générateurs des chambres d'épreuve."},{"n":"Araignée venimeuse","c":"Drops","p":"drops.html","d":"Exclusivement via les générateurs entourés de toiles dans les mines abandonnées."},{"n":"Slime","c":"Drops","p":"drops.html","d":"Sous Y = 40 dans environ 1 chunk sur 10 (« slime chunks », déterminés par la graine du monde), et dans les marais entre Y 50 et 70 par nuit "},{"n":"Poisson d'argent (Silverfish)","c":"Drops","p":"drops.html","d":"Blocs infestés en montagne et dans les forteresses (près du portail de l'End)."},{"n":"Phantom","c":"Drops","p":"drops.html","d":"Apparaît au-dessus du joueur quand il n'a pas dormi depuis 3 jours en jeu et se trouve à ciel ouvert."},{"n":"Grinceur (Creaking)","c":"Drops","p":"drops.html","d":"Forêt pâle (pale garden), la nuit, engendré par un « cœur de grinceur » (creaking heart) présent dans les troncs de chêne pâle."},{"n":"Pillard (Pillager)","c":"Drops","p":"drops.html","d":"Avant-postes de pillards, patrouilles aléatoires en surface, vagues de raid."},{"n":"Vindicateur","c":"Drops","p":"drops.html","d":"Manoirs des bois, raids de village."},{"n":"Évocateur","c":"Drops","p":"drops.html","d":"Manoirs des bois (salle secrète) et vague finale des raids."},{"n":"Ravageur","c":"Drops","p":"drops.html","d":"Vagues avancées de raid, monté par un pillard ou un évocateur."},{"n":"Vex","c":"Drops","p":"drops.html","d":"Invoqué par les évocateurs — traverse les murs."},{"n":"Breeze","c":"Drops","p":"drops.html","d":"Générateurs d'épreuve dans les chambres d'épreuve (trial chambers)."},{"n":"Gardien (Guardian)","c":"Drops","p":"drops.html","d":"Uniquement dans et autour des monuments océaniques."},{"n":"Grand gardien (Elder Guardian)","c":"Drops","p":"drops.html","d":"Trois par monument océanique : un au sommet, deux dans les ailes."},{"n":"Warden","c":"Drops","p":"drops.html","d":"Cité antique (deep dark), invoqué par 3 alertes de « hurleur sculk ». Ne peut pas apparaître naturellement autrement."},{"n":"Blaze","c":"Drops","p":"drops.html","d":"Forteresses du Nether, presque exclusivement via les générateurs de Blaze."},{"n":"Ghast","c":"Drops","p":"drops.html","d":"Vastes espaces ouverts : mer de lave, deltas de basalte, vallées de sable des âmes."},{"n":"Wither squelette","c":"Drops","p":"drops.html","d":"Forteresses du Nether, sur les blocs de briques du Nether (lumière ≤ 11)."},{"n":"Piglin","c":"Drops","p":"drops.html","d":"Forêts écarlates, deltas de basalte, vallées de sable des âmes, bastions."},{"n":"Piglin barbare","c":"Drops","p":"drops.html","d":"Bastions uniquement."},{"n":"Hoglin","c":"Drops","p":"drops.html","d":"Forêts écarlates et bastions."},{"n":"Piglin zombifié (Zombified Piglin)","c":"Drops","p":"drops.html","d":"Partout dans le Nether ; apparaît aussi dans le Surworld près d'un portail actif, ou quand un cochon est frappé par la foudre."},{"n":"Cube de magma","c":"Drops","p":"drops.html","d":"Partout dans le Nether, surtout dans les deltas de basalte et les bastions."},{"n":"Arpenteur (Strider)","c":"Drops","p":"drops.html","d":"Sur les mers de lave du Nether."},{"n":"Shulker","c":"Drops","p":"drops.html","d":"Cités de l'End, sur les murs et les tours."},{"n":"Endermite","c":"Drops","p":"drops.html","d":"0,4 % de chance d'apparaître quand un joueur lance une perle de l'Ender."},{"n":"Ender Dragon","c":"Drops","p":"drops.html","d":"Île centrale de l'End. Réinvocable avec 4 cristaux de l'End posés sur les bords du portail de sortie."},{"n":"Wither","c":"Drops","p":"drops.html","d":"Invoqué : 4 blocs de sable des âmes en T + 3 crânes de Wither squelette au sommet."},{"n":"Vache","c":"Drops","p":"drops.html","d":"Plaines, forêts, prairies — sur l'herbe, à la lumière."},{"n":"Mooshroom (vache-champignon)","c":"Drops","p":"drops.html","d":"Uniquement dans le biome « champs de champignons » (mushroom fields), extrêmement rare."},{"n":"Mouton","c":"Drops","p":"drops.html","d":"Plaines, forêts, prairies."},{"n":"Poule","c":"Drops","p":"drops.html","d":"Plaines et forêts."},{"n":"Cochon","c":"Drops","p":"drops.html","d":"Plaines et forêts."},{"n":"Lapin","c":"Drops","p":"drops.html","d":"Déserts, plaines enneigées, taïgas, forêts de fleurs."},{"n":"Abeille","c":"Drops","p":"drops.html","d":"Autour des nids d'abeilles, dans les biomes fleuris, forêts de bouleaux et prairies."},{"n":"Villageois","c":"Drops","p":"drops.html","d":"Villages, igloos (sous-sol), fermes de zombies-villageois soignés."},{"n":"Marchand ambulant","c":"Drops","p":"drops.html","d":"Apparaît aléatoirement près du joueur, accompagné de 2 lamas de marchand."},{"n":"Golem de fer","c":"Drops","p":"drops.html","d":"Villages (1 pour 10 villageois avec lit), ou construit : 4 blocs de fer en T + citrouille sculptée."},{"n":"Golem de neige","c":"Drops","p":"drops.html","d":"Construit : 2 blocs de neige + citrouille sculptée au sommet."},{"n":"Loup","c":"Drops","p":"drops.html","d":"Forêts, taïgas, toundras, bosquets — variantes visuelles selon le biome."},{"n":"Tatou (Armadillo)","c":"Drops","p":"drops.html","d":"Savanes et savanes en plateau."},{"n":"Renifleur (Sniffer)","c":"Drops","p":"drops.html","d":"Éclos d'un œuf de renifleur, obtenu en brossant le SABLE suspect des ruines sous-marines chaudes (et non les ruines de sentier)."},{"n":"Axolotl","c":"Drops","p":"drops.html","d":"Grottes luxuriantes, dans l'eau sous Y = 63, sur de l'argile."},{"n":"Chèvre","c":"Drops","p":"drops.html","d":"Pics enneigés, versants, bosquets."},{"n":"Tortue","c":"Drops","p":"drops.html","d":"Plages chaudes ; pond ses œufs sur le sable de sa plage natale."},{"n":"Grenouille","c":"Drops","p":"drops.html","d":"Marais et marais de mangrove ; 3 variantes selon le biome où le têtard grandit (tempéré, froid, chaud)."},{"n":"Allay","c":"Drops","p":"drops.html","d":"Cages des avant-postes de pillards et des manoirs des bois."},{"n":"Poissons (morue, saumon, poisson-globe, tropical)","c":"Drops","p":"drops.html","d":"Océans selon leur température ; le saumon aussi en rivières et rivières glacées."},{"n":"Poulpe / poulpe luisant","c":"Drops","p":"drops.html","d":"Poulpe : toute eau sous Y = 63. Poulpe luisant : grottes noyées, dans le noir."},{"n":"Minerai de diamant","c":"Drops","p":"drops.html","d":"Y -64 à +16, pic de densité à Y = -59. Plus fréquent quand il est exposé à l'air (grottes, ravins, cités antiques)."},{"n":"Minerai de fer","c":"Drops","p":"drops.html","d":"Deux pics : Y = 16 (grottes) et Y = 232 (sommets des montagnes). Présent de Y -64 à 320."},{"n":"Minerai d'or","c":"Drops","p":"drops.html","d":"Y -64 à +32, pic à Y = -16. Dans les mesas / badlands : gisements énormes entre Y 32 et 256, à ciel ouvert."},{"n":"Minerai de redstone","c":"Drops","p":"drops.html","d":"Y -64 à +15, densité maximale sous Y = -32, pic à Y = -59."},{"n":"Minerai de cuivre","c":"Drops","p":"drops.html","d":"Y -16 à +112, pic à Y = 48. Gisements géants dans les grottes de dripstone."},{"n":"Minerai de lapis-lazuli","c":"Drops","p":"drops.html","d":"Y -64 à +64, pic à Y = 0."},{"n":"Minerai d'émeraude","c":"Drops","p":"drops.html","d":"UNIQUEMENT dans les biomes de montagne (versants, pics, bosquets, prairies), Y -16 à 320, pic à Y = 236."},{"n":"Débris antiques (Ancient Debris)","c":"Drops","p":"drops.html","d":"Nether, Y 8 à 119, pic à Y = 15. Jamais exposé à l'air : impossible de le voir depuis une grotte."},{"n":"Minerai de quartz du Nether","c":"Drops","p":"drops.html","d":"Partout dans le Nether, entre Y 10 et 117, très abondant dans les deltas de basalte."},{"n":"Géode d'améthyste","c":"Drops","p":"drops.html","d":"Sphères creuses entre Y -64 et +30, souvent visibles depuis un océan ou une grotte (calcite + basalte lisse)."},{"n":"Bloc de sculk / cité antique","c":"Drops","p":"drops.html","d":"Biome deep dark, généralement sous Y = 0, sous les montagnes."},{"n":"Obsidienne","c":"Drops","p":"drops.html","d":"Là où de l'eau touche une source de lave, autour des lacs de lave sous Y 0, et dans les portails ruinés."},{"n":"Village","c":"Drops","p":"drops.html","d":"Plaines, déserts, savanes, taïgas, toundras enneigées."},{"n":"Donjon (salle du générateur)","c":"Drops","p":"drops.html","d":"Petites salles de pierres moussues sous terre, avec un générateur de zombies, squelettes ou araignées, et 1–2 coffres."},{"n":"Mine abandonnée","c":"Drops","p":"drops.html","d":"Réseaux de tunnels avec rails, entre Y -60 et 30 (jusqu'en surface dans les badlands)."},{"n":"Forteresse (Stronghold)","c":"Drops","p":"drops.html","d":"Entre 128 et 3 000 blocs du centre du monde, en anneaux ; localisée en lançant des yeux de l'Ender."},{"n":"Temple du désert","c":"Drops","p":"drops.html","d":"Pyramides de grès dans les déserts."},{"n":"Temple de la jungle","c":"Drops","p":"drops.html","d":"Jungles denses, en pierres moussues."},{"n":"Manoir des bois","c":"Drops","p":"drops.html","d":"Uniquement en forêt sombre, souvent à plusieurs milliers de blocs ; localisable via la carte de l'explorateur des bois (cartographe)."},{"n":"Monument océanique","c":"Drops","p":"drops.html","d":"Océans profonds, en prismarine, gardé par 3 grands gardiens."},{"n":"Bastion (Nether)","c":"Drops","p":"drops.html","d":"Nether, tous biomes sauf mers de lave. Quatre types : trésor, pont, écuries de hoglin, salle des piglins."},{"n":"Forteresse du Nether","c":"Drops","p":"drops.html","d":"Nether, en bandes traversant plusieurs biomes ; visible de loin grâce à ses ponts."},{"n":"Cité de l'End","c":"Drops","p":"drops.html","d":"Îles extérieures de l'End (après la passerelle du portail de sortie ou une perle de l'Ender)."},{"n":"Chambres d'épreuve (Trial Chambers)","c":"Drops","p":"drops.html","d":"Complexes en tuf et cuivre, entre Y -40 et +20, dans la plupart des biomes du Surworld."},{"n":"Ruines de sentier (Trail Ruins)","c":"Drops","p":"drops.html","d":"Enterrées dans les taïgas, jungles, forêts de bouleaux, marais de mangrove, plaines enneigées."},{"n":"Trésor enfoui","c":"Drops","p":"drops.html","d":"Sous les plages et le fond des océans — localisé grâce à la carte au trésor des épaves et des ruines sous-marines."},{"n":"Épave / ruines sous-marines","c":"Drops","p":"drops.html","d":"Fond des océans et parfois échouées sur les plages."},{"n":"Portail ruiné","c":"Drops","p":"drops.html","d":"Partout dans le Surworld et le Nether, entouré d'or brut et de blocs corrompus."},{"n":"Igloo","c":"Drops","p":"drops.html","d":"Plaines enneigées et taïgas enneigées."},{"n":"Nautile (Nautilus)","c":"Drops","p":"drops.html","d":"Créature aquatique (catégorie water_creature), toujours en groupe de 1. Poids 5 dans ocean, warm_ocean, lukewarm_ocean, deep_ocean et deep_l"},{"n":"Desséché (Parched)","c":"Drops","p":"drops.html","d":"Uniquement dans le biome desert, catégorie monster, poids 50, par groupes de 4 exactement (minCount = maxCount = 4). Il cohabite avec le mom"},{"n":"Golem de cuivre (Copper Golem)","c":"Drops","p":"drops.html","d":"Aucun fichier de biome ne le déclare dans ses spawners : il n'apparaît naturellement nulle part. On le bâtit, comme un golem de fer, mais av"},{"n":"Dromadaire momifié (Camel Husk)","c":"Drops","p":"drops.html","d":"Aucun fichier de worldgen/biome ne le liste dans ses spawners. En revanche la table de butin du momifié le désigne comme monture : un momifi"},{"n":"Nautile-zombie (Zombie Nautilus)","c":"Drops","p":"drops.html","d":"Aucun spawner de biome ne le mentionne. Les données définissent en revanche deux variantes d'apparence : « temperate » par défaut (priorité "},{"n":"Cube de soufre (Sulfur Cube)","c":"Drops","p":"drops.html","d":"Biome sulfur_caves uniquement, catégorie monster, poids 100 — le poids le plus élevé du biome, devant le creeper, le squelette et le zombie "},{"n":"Ghast joyeux (Happy Ghast)","c":"Drops","p":"drops.html","d":"Aucun spawner de biome ne le déclare : on l'obtient en posant un bloc Ghast desséché dans l'eau. Immergé, le bloc monte d'un palier d'hydrat"},{"n":"Mannequin (Mannequin)","c":"Drops","p":"drops.html","d":"Aucun spawner de biome, aucun œuf d'apparition, aucune recette. Le seul point d'entrée visible dans les données est la clé de traduction com"},{"n":"Lances (Spears)","c":"Drops","p":"drops.html","d":"Fabricables dans les 7 matériaux (bois, pierre, cuivre, fer, or, diamant, netherite). On en trouve aussi en coffre : forge de village (lance"},{"n":"Armure pour nautile (Nautilus Armor)","c":"Drops","p":"drops.html","d":"Cinq variantes : cuivre, fer, or, diamant, netherite. Aucune recette d'artisanat n'existe pour les quatre premières — seul netherite_nautilu"},{"n":"Armure en cuivre pour cheval (Copper Horse Armor)","c":"Drops","p":"drops.html","d":"Aucune recette dans data/minecraft/recipe/. On la trouve exclusivement en coffre : pyramide du désert (poids 15, à égalité avec l'armure en "},{"n":"Outils et armure en cuivre (Copper tools & armor)","c":"Drops","p":"drops.html","d":"Dix objets nouveaux fabricables : épée, pioche, hache, pelle, houe et lance en cuivre, plus casque, plastron, jambières et bottes en cuivre."},{"n":"Ghast desséché (Dried Ghast)","c":"Drops","p":"drops.html","d":"Fabricable, ou obtenu par troc avec un piglin : il figure dans gameplay/piglin_bartering.json avec un poids de 10 pour 1 exemplaire."},{"n":"Soufre et cinabre (Sulfur & Cinnabar)","c":"Drops","p":"drops.html","d":"Les deux blocs constituent la matière des grottes de soufre : les règles de surface du Surworld les placent dans ce seul biome, selon le bru"},{"n":"Planches","c":"Recette","p":"craft.html","d":"1 bûche de n'importe quelle essence donne 4 planches de la même essence. Le tout premier craft de chaque partie."},{"n":"Bâton","c":"Recette","p":"craft.html","d":"2 bambous donnent aussi 1 bâton : utile si vous êtes en jungle sans arbre à portée."},{"n":"Établi","c":"Recette","p":"craft.html","d":"Débloque la grille 3×3. À poser dans la base ET à emporter dans le sac pour crafter en expédition."},{"n":"Fourneau","c":"Recette","p":"craft.html","d":"Fait fondre minerais bruts, cuit la nourriture, transforme le sable en verre. 8 pierres suffisent."},{"n":"Coffre","c":"Recette","p":"craft.html","d":"Deux coffres côte à côte fusionnent en grand coffre (54 emplacements), sauf si un chat dort dessus."},{"n":"Torche","c":"Recette","p":"craft.html","d":"Le charbon de bois (bûche cuite au four) marche aussi et se renouvelle sans miner."},{"n":"Lit","c":"Recette","p":"craft.html","d":"Fixe votre point de réapparition et passe la nuit. ATTENTION : un lit explose dans le Nether et dans l'End (astuce pour miner les débris ant"},{"n":"Porte en bois","c":"Recette","p":"craft.html","d":"Les zombies enfoncent les portes en bois en Difficile. En base exposée, utilisez une porte en fer + plaque de pression."},{"n":"Échelle","c":"Recette","p":"craft.html","d":"Le moyen le moins cher de monter/descendre. Les échelles annulent les dégâts de chute si vous vous y accrochez."},{"n":"Seau","c":"Recette","p":"craft.html","d":"Un seau d'eau annule toute chute (MLG bucket), éteint le feu et crée des sources infinies (2 sources en diagonale)."},{"n":"Cisaille","c":"Recette","p":"craft.html","d":"Tond les moutons sans les tuer, récolte feuilles/toiles/lianes intactes et récupère les rayons de miel."},{"n":"Briquet","c":"Recette","p":"craft.html","d":"Allume les portails du Nether, le TNT et les feux de camp. Le silex vient du gravier (10 % de chance)."},{"n":"Bateau","c":"Recette","p":"craft.html","d":"Ajoutez un coffre au bateau pour un bateau-coffre. En bateau, on ne subit ni la fatigue ni les mobs marins."},{"n":"Pioche","c":"Recette","p":"craft.html","d":"Remplacez M par : planches, pierre, lingot de CUIVRE, lingot de fer, lingot d'or ou diamant. Progression : bois → pierre → cuivre → fer → di"},{"n":"Hache","c":"Recette","p":"craft.html","d":"Meilleure arme en dégâts bruts, mais plus lente que l'épée. Elle brise aussi les boucliers pendant 5 secondes."},{"n":"Pelle","c":"Recette","p":"craft.html","d":"Crée aussi les chemins de terre (clic droit sur l'herbe) : idéal pour tracer les allées d'un village."},{"n":"Houe","c":"Recette","p":"craft.html","d":"Laboure la terre et récolte plus vite les cultures. En netherite avec Fortune, c'est l'outil de récolte définitif."},{"n":"Épée","c":"Recette","p":"craft.html","d":"Coup balayant (sprint désactivé + attaque chargée) : touche tous les mobs adjacents. Base de toute ferme manuelle."},{"n":"Arc","c":"Recette","p":"craft.html","d":"3 bâtons en diagonale + 3 ficelles alignées à droite. Enchantez Infinité + Puissance pour un arc éternel."},{"n":"Flèche","c":"Recette","p":"craft.html","d":"Une ferme à squelettes rend ce craft inutile : elle produit directement des flèches par milliers."},{"n":"Lance (spear)","c":"Recette","p":"craft.html","d":"Arme d'hast à longue portée, déclinée dans tous les matériaux (bois à diamant), et améliorable en netherite à la table de forge. Elle frappe"},{"n":"Étiquette (name tag)","c":"Recette","p":"craft.html","d":"Désormais FABRICABLE : 1 papier + 1 pépite de métal en diagonale. Il fallait auparavant la pêcher ou la trouver en coffre. Nommez un mob à l"},{"n":"Bouclier","c":"Recette","p":"craft.html","d":"Bloque 100 % des dégâts de face, y compris les flèches et les explosions de creeper. À tenir en main secondaire (F)."},{"n":"Canne à pêche","c":"Recette","p":"craft.html","d":"Avec Chance de la mer III + Appât III : la pêche devient une source d'objets enchantés, de selles et de noms de disques."},{"n":"Longue-vue","c":"Recette","p":"craft.html","d":"Zoom ×10. Indispensable pour repérer un manoir, une cité de l'End ou une structure de loin sans se déplacer."},{"n":"Brosse (archéologie)","c":"Recette","p":"craft.html","d":"Balaie le sable/gravier suspect des ruines de sentier et des sites de fouille : tessons de poterie, œufs de sniffer."},{"n":"Casque","c":"Recette","p":"craft.html","d":"5 unités de matériau. Enchantez Respiration + Affinité aquatique pour les chantiers sous-marins."},{"n":"Plastron","c":"Recette","p":"craft.html","d":"8 unités : la pièce la plus chère et la plus protectrice. À prioriser si vos ressources sont limitées."},{"n":"Jambières","c":"Recette","p":"craft.html","d":"7 unités. Deuxième priorité de protection après le plastron."},{"n":"Bottes","c":"Recette","p":"craft.html","d":"4 unités. Chute amortie IV supprime quasiment tous les dégâts de chute : le meilleur enchantement de confort du jeu."},{"n":"Amélioration en netherite","c":"Recette","p":"craft.html","d":"Table de forge : modèle d'amélioration netherite (trouvé en bastion) + équipement en diamant + 1 lingot de netherite. L'objet garde ses ench"},{"n":"Lingot de netherite","c":"Recette","p":"craft.html","d":"4 éclats de netherite (débris antiques fondus) + 4 lingots d'or, dans n'importe quelle disposition. Comptez ~4 débris par lingot."},{"n":"Torche de redstone","c":"Recette","p":"craft.html","d":"Source d'énergie permanente et inverseur logique (NON) : c'est le composant fondamental de toute la logique redstone."},{"n":"Répéteur","c":"Recette","p":"craft.html","d":"Régénère le signal à 15, impose un sens unique et ajoute 1 à 4 ticks de délai (clic droit). Verrouillable par un signal latéral."},{"n":"Comparateur","c":"Recette","p":"craft.html","d":"Lit le remplissage d'un conteneur (coffre, entonnoir, four) et compare deux signaux. Cœur des trieurs automatiques et des horloges."},{"n":"Piston","c":"Recette","p":"craft.html","d":"Pousse jusqu'à 12 blocs. Certains blocs (obsidienne, coffres, établis) ne peuvent pas être poussés."},{"n":"Piston collant","c":"Recette","p":"craft.html","d":"Ramène le bloc poussé. Une boule de miel fonctionne aussi… mais miel et slime ne collent pas entre eux : la base des machines volantes."},{"n":"Observateur","c":"Recette","p":"craft.html","d":"Émet une impulsion d'1 tick quand le bloc devant lui change d'état. Détecteur universel : cultures, pistons, portes, eau."},{"n":"Entonnoir (hopper)","c":"Recette","p":"craft.html","d":"Aspire les objets au-dessus et transfère vers le conteneur qu'il vise. Un signal de redstone le DÉSACTIVE (logique inversée)."},{"n":"Distributeur (dispenser)","c":"Recette","p":"craft.html","d":"Utilise l'objet (tire une flèche, verse un seau, plante un plant, tond un mouton). Le cœur des fermes automatisées."},{"n":"Lanceur (dropper)","c":"Recette","p":"craft.html","d":"Éjecte simplement l'objet, sans l'utiliser. Chaîné, il transporte des objets vers le haut — l'inverse d'un entonnoir."},{"n":"Fabricateur (crafter)","c":"Recette","p":"craft.html","d":"Craft automatiquement dès qu'il reçoit un signal de redstone : permet des usines de blocs, de flèches, de pains entièrement automatiques."},{"n":"Rails","c":"Recette","p":"craft.html","d":"6 lingots + 1 bâton pour 16 rails. Les mines abandonnées en fournissent gratuitement des centaines."},{"n":"Rail motorisé","c":"Recette","p":"craft.html","d":"Alimenté, il accélère ; non alimenté, il freine. Un rail motorisé tous les 8 rails suffit sur du plat."},{"n":"TNT","c":"Recette","p":"craft.html","d":"5 poudres à canon + 4 sables. Le sable rouge marche aussi. Base des canons, des fermes à arbres et du minage de débris antiques."},{"n":"Plaque de pression","c":"Recette","p":"craft.html","d":"En pierre : joueurs et mobs. En bois : tout, y compris les objets au sol. En or/fer : plaques « pesantes », signal proportionnel au nombre d"},{"n":"Levier","c":"Recette","p":"craft.html","d":"Le seul interrupteur qui garde son état indéfiniment. À privilégier pour couper une ferme."},{"n":"Table d'enchantement","c":"Recette","p":"craft.html","d":"Entourée de 15 bibliothèques à 2 blocs de distance (avec 1 bloc d'air entre), elle atteint le niveau 30."},{"n":"Bibliothèque","c":"Recette","p":"craft.html","d":"3 livres + 6 planches. Il en faut 15 autour de la table d'enchantement : prévoyez 45 livres, donc 45 cuirs et 135 papiers."},{"n":"Enclume","c":"Recette","p":"craft.html","d":"31 lingots de fer au total. Combine deux objets, applique un livre enchanté, répare et renomme. Elle s'use : gardez-en une de rechange."},{"n":"Meule (grindstone)","c":"Recette","p":"craft.html","d":"Retire les enchantements d'un objet et RÉCUPÈRE l'XP. Idéal pour recycler l'équipement d'une ferme à mobs."},{"n":"Alambic","c":"Recette","p":"craft.html","d":"1 bâton de Blaze + 3 pierres. Le bâton reste dans l'alambic comme carburant : 1 bâton = 20 brassages."},{"n":"Chaudron","c":"Recette","p":"craft.html","d":"Stocke eau, lave ou poudre de neige. Sous un bloc de stalactite, il se remplit tout seul : source d'eau et de lave renouvelable."},{"n":"Balise (beacon)","c":"Recette","p":"craft.html","d":"Sur une pyramide de 9/34/83/164 blocs (fer, or, diamant, émeraude ou netherite) : Célérité, Hâte, Résistance, Saut, Force sur un large rayon"},{"n":"Haut fourneau","c":"Recette","p":"craft.html","d":"Fond minerais et équipements deux fois plus vite qu'un four (mais donne moitié moins d'XP). Métier : armurier."},{"n":"Fumoir","c":"Recette","p":"craft.html","d":"Cuit la nourriture deux fois plus vite. Métier : boucher. Indispensable à côté d'une ferme à animaux."},{"n":"Table de forge (smithing)","c":"Recette","p":"craft.html","d":"Applique les améliorations netherite et les ornements d'armure (armor trims). Métier : armurier d'outils."},{"n":"Métier à tisser (loom)","c":"Recette","p":"craft.html","d":"Applique les motifs de bannière sans consommer la grille 3×3. Métier : berger."},{"n":"Table de cartographie","c":"Recette","p":"craft.html","d":"2 papiers + 4 planches. Agrandit, copie et verrouille les cartes. Métier : cartographe (vend les cartes du manoir et du monument)."},{"n":"Composteur","c":"Recette","p":"craft.html","d":"7 dalles en bois. Transforme graines, cultures et déchets végétaux en poudre d'os. Métier : fermier."},{"n":"Tonneau","c":"Recette","p":"craft.html","d":"6 planches + 2 dalles. Même capacité qu'un coffre, s'ouvre même avec un bloc au-dessus. Métier : pêcheur."},{"n":"Lutrin","c":"Recette","p":"craft.html","d":"Bloc de métier du bibliothécaire — le commerce le plus rentable du jeu (livres enchantés contre émeraudes)."},{"n":"Pain","c":"Recette","p":"craft.html","d":"3 blés. La ressource alimentaire la plus facile à industrialiser (ferme à blé + villageois fermier)."},{"n":"Carotte dorée","c":"Recette","p":"craft.html","d":"Le meilleur aliment du jeu en saturation. Ingrédient de la potion de Vision nocturne."},{"n":"Pomme dorée","c":"Recette","p":"craft.html","d":"8 lingots d'or. Absorption + Régénération. La version « enchantée » ne se craft plus : elle se trouve uniquement en coffre."},{"n":"Gâteau","c":"Recette","p":"craft.html","d":"3 seaux de lait (rendus vides), 2 sucres, 1 œuf, 3 blés. Se mange posé au sol, 7 parts."},{"n":"Soupe de champignons","c":"Recette","p":"craft.html","d":"1 champignon rouge + 1 brun + 1 bol. Sur une mooshroom : un clic avec un bol suffit, ressource illimitée."},{"n":"Cookies","c":"Recette","p":"craft.html","d":"2 blés + 1 fève de cacao (jungle) donnent 8 cookies : le meilleur rendement calorique par blé."},{"n":"Melon scintillant","c":"Recette","p":"craft.html","d":"Ne se mange pas : c'est l'ingrédient de la potion de Soin instantané."},{"n":"Wagonnet","c":"Recette","p":"craft.html","d":"Combinez-le avec un coffre, un entonnoir, un TNT ou un four pour des variantes automatisables."},{"n":"Boîte de shulker","c":"Recette","p":"craft.html","d":"2 carapaces de shulker + 1 coffre. Conserve son contenu quand on la casse : LE conteneur portable. Teintable et empilable dans un coffre."},{"n":"Cadre d'objet","c":"Recette","p":"craft.html","d":"Sert de repère visuel sur les coffres d'un système de tri, et d'affichage pour une carte murale géante."},{"n":"Boussole de récupération","c":"Recette","p":"craft.html","d":"8 éclats d'écho (Warden) + 1 BOUSSOLE au centre — et non un cœur de la mer, qui sert au conduit. Pointe vers votre dernier lieu de mort."},{"n":"Échafaudage","c":"Recette","p":"craft.html","d":"6 bambous + 1 ficelle, celle-ci en HAUT au centre. Se pose en chaîne vers le haut ou latéralement : l'outil de construction verticale par ex"},{"n":"Œil de l'Ender","c":"Recette","p":"craft.html","d":"1 perle de l'Ender + 1 poudre de Blaze. Localise la forteresse et active le portail de l'End. Prévoyez-en 15 à 20."},{"n":"Cristal de l'End","c":"Recette","p":"craft.html","d":"Réel : 7 verres + 1 œil de l'Ender + 1 larme de Ghast. Quatre cristaux posés sur le portail de sortie réinvoquent le dragon."},{"n":"Bloc de sable des âmes → invocation du Wither","c":"Recette","p":"craft.html","d":"Pas un craft mais une construction : un T de 4 sables des âmes surmonté de 3 crânes de squelette wither. Posez le dernier crâne en dernier."},{"n":"Masse (Mace)","c":"Recette","p":"craft.html","d":"Cœur alourdi (coffre-fort ominous des chambres d'épreuve) posé AU-DESSUS d'une tige de Breeze, à l'établi — pas à la table de forge. Ses dég"},{"n":"Lanterne","c":"Recette","p":"craft.html","d":"8 pépites de FER (pas d'or) + 1 torche. Se suspend aux plafonds et aux chaînes : l'éclairage le plus élégant du jeu."},{"n":"Chaîne","c":"Recette","p":"craft.html","d":"2 pépites de fer + 1 lingot de fer. Suspend les lanternes en grappes ou décore les entrepôts et les mines. Une variante en cuivre existe aus"},{"n":"Bougie","c":"Recette","p":"craft.html","d":"Jusqu'à 4 par bloc, teintables en 16 couleurs, allumables au briquet. Sur un gâteau, elles servent pour l'anniversaire."},{"n":"Bannière","c":"Recette","p":"craft.html","d":"6 laines + 1 bâton. À décorer au métier à tisser. Une bannière copiée sur une carte y ajoute un marqueur nommé."},{"n":"Poudre de béton","c":"Recette","p":"craft.html","d":"4 sables + 4 graviers + 1 colorant = 8 poudres. Au contact de l'eau, elle durcit en béton : le bloc de construction moderne par excellence."},{"n":"Papier","c":"Recette","p":"craft.html","d":"3 cannes à sucre → 3 papiers. Base des livres, des cartes et des fusées de feu d'artifice (élytre !)."},{"n":"Livre","c":"Recette","p":"craft.html","d":"3 papiers + 1 cuir, sans forme imposée. Multipliez par 45 pour équiper une salle d'enchantement complète."},{"n":"Fusée de feu d'artifice","c":"Recette","p":"craft.html","d":"1 papier + 1 à 3 poudres à canon (la durée = la portée). Avec l'élytre, c'est le moteur : une fusée toutes les 5 secondes de vol."},{"n":"Verre","c":"Recette","p":"craft.html","d":"Cuisson au four. 6 verres → 16 vitres. Le verre teinté (verre + colorant) ne se transforme pas en vitre."},{"n":"Escaliers","c":"Recette","p":"craft.html","d":"6 blocs donnent 4 escaliers — une perte de 33 %. Passez par le tailleur de pierre : 1 bloc = 1 escalier, sans perte."},{"n":"Dalles","c":"Recette","p":"craft.html","d":"Une dalle inférieure empêche toute apparition de monstre : c'est le moyen le moins cher de sécuriser une grande surface."},{"n":"Muret","c":"Recette","p":"craft.html","d":"Le muret compte pour 1,5 bloc de hauteur, comme une clôture. Indispensable pour les créneaux et les balustrades."},{"n":"Briques de pierre","c":"Recette","p":"craft.html","d":"4 pierres (pas du cobblestone : il faut la cuire d'abord). Le matériau de référence des châteaux et des donjons."},{"n":"Bloc de briques","c":"Recette","p":"craft.html","d":"La brique s'obtient en cuisant une boule d'argile. Comptez 4 briques par bloc : une cheminée en consomme vite plusieurs piles."},{"n":"Bloc compact (fer, or, diamant…)","c":"Recette","p":"craft.html","d":"9 unités → 1 bloc, et l'inverse rend les 9 unités. Vaut pour fer, or, cuivre, diamant, émeraude, redstone, lapis, charbon, netherite et slim"},{"n":"Bloc de foin","c":"Recette","p":"craft.html","d":"9 blés. Sert au stockage compact, à nourrir chevaux et lamas, et amortit totalement les chutes (avec 1 bloc d'eau dessus)."},{"n":"Bloc de laine","c":"Recette","p":"craft.html","d":"4 ficelles. Utile quand une ferme à araignées produit plus de ficelle que vous n'avez de moutons."},{"n":"Tapis","c":"Recette","p":"craft.html","d":"Posé sur un bloc lumineux, il masque la source de lumière : c'est l'astuce d'éclairage invisible des constructeurs."},{"n":"Barreaux de fer","c":"Recette","p":"craft.html","d":"6 lingots pour 16 barreaux. Fenêtres de donjon, cages, herses de châtelet."},{"n":"Verre teinté","c":"Recette","p":"craft.html","d":"8 verres + 1 colorant. Le verre teinté ne se transforme pas en vitre — pensez-y avant de tout teindre."},{"n":"Pierre lumineuse","c":"Recette","p":"craft.html","d":"4 poudres lumineuses (Nether ou sorcières). Lumière 15, et composant de la lampe de redstone."},{"n":"Lampe de redstone","c":"Recette","p":"craft.html","d":"4 poudres de redstone + 1 pierre lumineuse. Le seul éclairage commutable du jeu."},{"n":"Torche des âmes","c":"Recette","p":"craft.html","d":"Charbon + bâton + sable des âmes. Lumière bleue de niveau 10 — et elle repousse les piglins."},{"n":"Feu de camp","c":"Recette","p":"craft.html","d":"3 bâtons + 1 charbon + 3 bûches. Cuit 4 aliments sans carburant, éclaire (15), et sa fumée calme les abeilles."},{"n":"Citrouille-lanterne","c":"Recette","p":"craft.html","d":"Citrouille sculptée + torche. Lumière 15 et posable sous l'eau : très utile pour éclairer un chantier sous-marin."},{"n":"Pot de fleurs","c":"Recette","p":"craft.html","d":"3 briques. Accepte fleurs, pousses, champignons, cactus et bambou : le détail qui rend un intérieur habité."},{"n":"Support à armure","c":"Recette","p":"craft.html","d":"6 bâtons + 1 dalle de pierre lisse. Range une armure, sert de mannequin décoratif et de repère de construction."},{"n":"Pot décoré","c":"Recette","p":"craft.html","d":"4 tessons de poterie (fouilles archéologiques) ou 4 briques. Chaque face garde le motif du tesson utilisé."},{"n":"Cadre lumineux","c":"Recette","p":"craft.html","d":"Cadre d'objet + sac d'encre luisant (calmar luisant). L'objet exposé reste visible dans le noir."},{"n":"Jukebox","c":"Recette","p":"craft.html","d":"8 planches + 1 diamant. Lit les disques ; un comparateur derrière lui indique quel disque est en lecture."},{"n":"Bloc de note","c":"Recette","p":"craft.html","d":"Le bloc placé DESSOUS détermine l'instrument (bois = basse, pierre = batterie, or = cloche, laine = guitare…)."},{"n":"Bouclier orné","c":"Recette","p":"craft.html","d":"Bannière + bouclier à l'établi : le motif de la bannière s'applique au bouclier. Purement esthétique, mais spectaculaire."},{"n":"Panneau","c":"Recette","p":"craft.html","d":"6 planches + 1 bâton. Un panneau bloque l'eau : c'est l'astuce de base pour créer des poches d'air sous-marines."},{"n":"Détecteur de lumière du jour","c":"Recette","p":"craft.html","d":"Signal proportionnel à la lumière du soleil. Un clic droit l'inverse : il devient un détecteur de nuit, idéal pour l'éclairage automatique."},{"n":"Rail détecteur","c":"Recette","p":"craft.html","d":"Émet un signal au passage d'un wagonnet. Avec un comparateur, il lit même le contenu d'un wagonnet-coffre."},{"n":"Rail activateur","c":"Recette","p":"craft.html","d":"Éjecte le passager d'un wagonnet ou amorce un wagonnet-TNT. Le composant des stations automatiques."},{"n":"Cible (target)","c":"Recette","p":"craft.html","d":"4 poudres de redstone autour d'1 bloc de foin. Émet un signal d'autant plus fort que la flèche touche près du centre : la base des portes à "},{"n":"Crochet de détente","c":"Recette","p":"craft.html","d":"Deux crochets reliés par de la ficelle forment un fil de détente : le déclencheur invisible des pièges et des portes secrètes."},{"n":"Wagonnet-coffre","c":"Recette","p":"craft.html","d":"Coffre + wagonnet déjà fabriqué, sans forme imposée. Transporte 27 emplacements sur rails ; un rail détecteur + comparateur permet de le déc"},{"n":"Colorant à partir d'une fleur","c":"Recette","p":"craft.html","d":"Chaque fleur donne son colorant : coquelicot → rouge, pissenlit → jaune, bleuet → bleu clair, orchidée → rose pâle. Les grandes fleurs en do"},{"n":"Colorants de base (sans fleur)","c":"Recette","p":"craft.html","d":"Blanc = poudre d'os · Noir = poche d'encre · Bleu = lapis · Vert = cactus cuit au four · Marron = fève de cacao · Rouge = coquelicot ou bett"},{"n":"Mélange de colorants","c":"Recette","p":"craft.html","d":"Rouge + jaune = orange · Rouge + blanc = rose · Bleu + vert = cyan · Bleu + rouge = violet · Noir + blanc = gris. Les 16 couleurs se déduise"},{"n":"Béton (durcissement)","c":"Recette","p":"craft.html","d":"Pas un craft : jetez la poudre de béton dans l'eau ou versez-y un seau. Elle durcit instantanément. Un bloc de béton durci ne se re-teinte p"},{"n":"Ragoût de lapin","c":"Recette","p":"craft.html","d":"Lapin cuit + carotte + pomme de terre cuite + champignon + bol. L'un des aliments les plus nourrissants, mais coûteux en ingrédients."},{"n":"Tarte à la citrouille","c":"Recette","p":"craft.html","d":"1 citrouille + 1 sucre + 1 œuf. Bien plus rentable que le gâteau : aucun seau de lait, et elle se mange à la main."},{"n":"Pomme dorée enchantée (recette supprimée)","c":"Recette","p":"craft.html","d":"La recette (8 blocs d'or + 1 pomme) a été RETIRÉE du jeu. Elle ne se trouve plus que dans les coffres : bastions, manoirs, temples, portails"},{"n":"Carte vierge","c":"Recette","p":"craft.html","d":"8 papiers + 1 boussole. Sans boussole, la carte existe mais n'affiche pas votre position. À agrandir à la table de cartographie."},{"n":"Livre et plume","c":"Recette","p":"craft.html","d":"Livre + plume + poche d'encre. Permet d'écrire un journal de coordonnées — bien plus fiable que la mémoire."},{"n":"Longe (laisse)","c":"Recette","p":"craft.html","d":"5 ficelles, et plus aucune boule de slime : la recette a été simplifiée. Attache les animaux à un piquet de clôture — le moyen le plus simpl"},{"n":"Cisaille à citrouille","c":"Recette","p":"craft.html","d":"Pas un craft : clic droit avec une cisaille sur une citrouille posée. Elle donne 4 pépins et devient sculptée — nécessaire aux golems."},{"n":"Bloc de charbon","c":"Recette","p":"craft.html","d":"9 charbons. Comme carburant, il cuit 80 objets contre 72 pour 9 charbons séparés : un léger gain, et surtout un stockage 9 fois plus compact"},{"n":"Potion étrange","c":"Potion","p":"potions.html","d":"Fiole d'eau + verrue du Nether"},{"n":"Potion épaisse","c":"Potion","p":"potions.html","d":"Fiole d'eau + poudre lumineuse"},{"n":"Potion banale","c":"Potion","p":"potions.html","d":"Fiole d'eau + presque n'importe quel ingrédient sans verrue"},{"n":"Force","c":"Potion","p":"potions.html","d":"Potion étrange + poudre de Blaze"},{"n":"Rapidité","c":"Potion","p":"potions.html","d":"Potion étrange + sucre"},{"n":"Résistance au feu","c":"Potion","p":"potions.html","d":"Potion étrange + crème de magma"},{"n":"Vision nocturne","c":"Potion","p":"potions.html","d":"Potion étrange + carotte dorée"},{"n":"Respiration aquatique","c":"Potion","p":"potions.html","d":"Potion étrange + poisson-globe"},{"n":"Soin instantané","c":"Potion","p":"potions.html","d":"Potion étrange + tranche de pastèque scintillante"},{"n":"Régénération","c":"Potion","p":"potions.html","d":"Potion étrange + larme de Ghast"},{"n":"Saut","c":"Potion","p":"potions.html","d":"Potion étrange + patte de lapin"},{"n":"Lenteur","c":"Potion","p":"potions.html","d":"Potion de Rapidité ou de Saut + œil d'araignée fermenté"},{"n":"Faiblesse","c":"Potion","p":"potions.html","d":"Fiole d'EAU + œil d'araignée fermenté (pas besoin de verrue !)"},{"n":"Poison","c":"Potion","p":"potions.html","d":"Potion étrange + œil d'araignée"},{"n":"Invisibilité","c":"Potion","p":"potions.html","d":"Potion de Vision nocturne + œil d'araignée fermenté"},{"n":"Dégâts instantanés","c":"Potion","p":"potions.html","d":"Potion de Soin ou de Poison + œil d'araignée fermenté"},{"n":"Chute lente","c":"Potion","p":"potions.html","d":"Potion étrange + membrane de Phantom"},{"n":"Maître Tortue","c":"Potion","p":"potions.html","d":"Potion étrange + carapace de tortue"},{"n":"Souffle (Wind Charged)","c":"Potion","p":"potions.html","d":"Potion étrange + bâton de Breeze"},{"n":"Viscosité et Tissage","c":"Potion","p":"potions.html","d":"Potion étrange + bloc de slime (Viscosité) ou toile d'araignée (Tissage)"},{"n":"Infestation","c":"Potion","p":"potions.html","d":"Potion étrange + roche"},{"n":"Solidité III (Unbreaking)","c":"Enchantement","p":"enchantements.html","d":"Tout objet ayant une durabilité : outils, armes, armures, arc, canne à pêche, briquet, cisaille, élytre."},{"n":"Raccommodage (Mending)","c":"Enchantement","p":"enchantements.html","d":"Tout objet ayant une durabilité."},{"n":"Malédiction de disparition","c":"Enchantement","p":"enchantements.html","d":"Tout objet."},{"n":"Malédiction du lien éternel","c":"Enchantement","p":"enchantements.html","d":"Armures, élytre, tête."},{"n":"Tranchant V (Sharpness)","c":"Enchantement","p":"enchantements.html","d":"Épée et hache."},{"n":"Châtiment V (Smite)","c":"Enchantement","p":"enchantements.html","d":"Épée et hache."},{"n":"Fléau des arthropodes V","c":"Enchantement","p":"enchantements.html","d":"Épée et hache."},{"n":"Butin III (Looting)","c":"Enchantement","p":"enchantements.html","d":"Épée uniquement."},{"n":"Aura de feu II (Fire Aspect)","c":"Enchantement","p":"enchantements.html","d":"Épée."},{"n":"Recul II (Knockback)","c":"Enchantement","p":"enchantements.html","d":"Épée."},{"n":"Affilage III (Sweeping Edge)","c":"Enchantement","p":"enchantements.html","d":"Épée."},{"n":"Efficacité V","c":"Enchantement","p":"enchantements.html","d":"Pioche, hache, pelle, cisaille."},{"n":"Fortune III","c":"Enchantement","p":"enchantements.html","d":"Pioche, hache (récolte), pelle, houe."},{"n":"Toucher de soie","c":"Enchantement","p":"enchantements.html","d":"Les outils de minage : pioche, hache, pelle, houe. PAS la cisaille."},{"n":"Puissance V (Power)","c":"Enchantement","p":"enchantements.html","d":"Arc."},{"n":"Infinité","c":"Enchantement","p":"enchantements.html","d":"Arc."},{"n":"Flamme","c":"Enchantement","p":"enchantements.html","d":"Arc."},{"n":"Frappe II (Punch)","c":"Enchantement","p":"enchantements.html","d":"Arc."},{"n":"Tir multiple / Perforation IV / Charge rapide III","c":"Enchantement","p":"enchantements.html","d":"Arbalète."},{"n":"Loyauté III / Impulsion III / Empalement V / Canalisation","c":"Enchantement","p":"enchantements.html","d":"Trident (drop des noyés)."},{"n":"Densité V / Brèche IV / Rafale de vent III","c":"Enchantement","p":"enchantements.html","d":"Masse (mace)."},{"n":"Protection IV","c":"Enchantement","p":"enchantements.html","d":"Toutes les pièces d'armure."},{"n":"Protections spécialisées IV","c":"Enchantement","p":"enchantements.html","d":"Toutes les pièces d'armure."},{"n":"Chute amortie IV (Feather Falling)","c":"Enchantement","p":"enchantements.html","d":"Bottes."},{"n":"Épines III (Thorns)","c":"Enchantement","p":"enchantements.html","d":"Toutes les pièces d'armure."},{"n":"Apnée III","c":"Enchantement","p":"enchantements.html","d":"Casque."},{"n":"Affinité aquatique","c":"Enchantement","p":"enchantements.html","d":"Casque."},{"n":"Agilité aquatique III (Depth Strider)","c":"Enchantement","p":"enchantements.html","d":"Bottes."},{"n":"Semelles givrantes II (Frost Walker)","c":"Enchantement","p":"enchantements.html","d":"Bottes."},{"n":"Agilité des âmes III (Soul Speed)","c":"Enchantement","p":"enchantements.html","d":"Bottes."},{"n":"Furtivité rapide III (Swift Sneak)","c":"Enchantement","p":"enchantements.html","d":"Jambières."},{"n":"Élan III (Lunge)","c":"Enchantement","p":"enchantements.html","d":"Lance (spear) — l'arme d'hast introduite avec cette version."},{"n":"Chance de la mer III / Appât III","c":"Enchantement","p":"enchantements.html","d":"Canne à pêche."},{"n":"Poudre de redstone","c":"Composant","p":"redstone.html","d":"Posée au sol, elle transporte le signal et perd 1 point de force par bloc parcouru."},{"n":"Torche de redstone","c":"Composant","p":"redstone.html","d":"Sur un bloc ou au sol. Elle émet un signal de force 15 en permanence."},{"n":"Répéteur","c":"Composant","p":"redstone.html","d":"Entre deux segments de poudre."},{"n":"Comparateur","c":"Composant","p":"redstone.html","d":"Derrière un conteneur, ou entre deux lignes de signal."},{"n":"Observateur","c":"Composant","p":"redstone.html","d":"Face au bloc à surveiller (le « visage » regarde la cible)."},{"n":"Piston et piston collant","c":"Composant","p":"redstone.html","d":"Partout. Le piston collant ramène le bloc poussé, le piston normal non."},{"n":"Entonnoir (hopper)","c":"Composant","p":"redstone.html","d":"Sous ou à côté d'un conteneur ; il pointe vers la cible au moment de la pose (accroupissez-vous pour viser)."},{"n":"Distributeur et lanceur","c":"Composant","p":"redstone.html","d":"Orientés vers la cible."},{"n":"Capteur de sculk","c":"Composant","p":"redstone.html","d":"Deep dark, ou posé où vous voulez (Toucher de soie)."},{"n":"Fabricateur (crafter)","c":"Composant","p":"redstone.html","d":"Alimenté par un entonnoir, déclenché par un signal."},{"n":"Porte NON (inverseur)","c":"Circuit","p":"redstone.html","a":"porte-non","d":"Le circuit le plus simple et le plus utilisé : la sortie est allumée quand l'entrée est éteinte."},{"n":"Porte ET (AND)","c":"Circuit","p":"redstone.html","a":"porte-et","d":"La sortie ne s'allume que si les DEUX entrées sont actives. Sert à conditionner une machine à deux verrous."},{"n":"Porte OU (OR)","c":"Circuit","p":"redstone.html","a":"porte-ou","d":"La sortie s'allume si AU MOINS une entrée est active. C'est simplement deux fils qui se rejoignent."},{"n":"Porte OU EXCLUSIF (XOR)","c":"Circuit","p":"redstone.html","a":"porte-xor","d":"La sortie s'allume si UNE SEULE entrée est active. C'est le circuit d'un interrupteur « va-et-vient » : deux leviers commandent la même lamp"},{"n":"Horloge à observateurs (1 tick)","c":"Circuit","p":"redstone.html","a":"horloge-obs","d":"L'horloge la plus rapide et la plus compacte du jeu : deux observateurs qui se regardent."},{"n":"Horloge à répéteurs (réglable)","c":"Circuit","p":"redstone.html","a":"horloge-rep","d":"Une boucle de poudre et de répéteurs : le délai se règle au clic. L'horloge polyvalente par défaut."},{"n":"Horloge à entonnoirs (lente)","c":"Circuit","p":"redstone.html","a":"horloge-hopper","d":"Des objets font l'aller-retour entre deux entonnoirs ; un comparateur lit le passage. La façon la plus économique de cadencer une ferme à la"},{"n":"Impulsion courte (monostable)","c":"Circuit","p":"redstone.html","a":"monostable","d":"Transforme un signal long (levier, plaque) en une impulsion brève. Indispensable pour les pistons collants et les portes automatiques."},{"n":"Verrou T (interrupteur à impulsion)","c":"Circuit","p":"redstone.html","a":"tflip","d":"Chaque impulsion bascule l'état : allumé, éteint, allumé… C'est ce qui transforme un bouton en interrupteur."},{"n":"Détecter un coffre plein","c":"Circuit","p":"redstone.html","a":"detect-plein","d":"Un comparateur lit le remplissage d'un conteneur. Sert à couper une ferme quand le stockage est saturé, ou à allumer un voyant."},{"n":"Porte cachée 2 × 2 à pistons","c":"Circuit","p":"redstone.html","a":"porte-2x2","d":"Un pan de mur qui s'ouvre sans laisser voir de mécanisme. Le classique de toute base secrète."},{"n":"Éclairage automatique à la tombée de la nuit","c":"Circuit","p":"redstone.html","a":"lampe-auto","d":"Vos lampes s'allument seules au coucher du soleil et s'éteignent à l'aube. Le montage de confort le plus rentable d'une base."},{"n":"Sas et rideau d'eau automatiques","c":"Circuit","p":"redstone.html","a":"canon-eau","d":"Un distributeur verse et reprend l'eau à la demande : rideau d'entrée, piège, ou évacuation d'un couloir de ferme."},{"n":"Bibliothécaire","c":"Métier","p":"villageois.html","d":"Bloc de métier : le lutrin (4 dalles de bois + 1 bibliothèque)."},{"n":"Fermier","c":"Métier","p":"villageois.html","d":"Bloc de métier : le composteur (7 dalles de bois)."},{"n":"Armurier","c":"Métier","p":"villageois.html","d":"Bloc de métier : le haut fourneau (5 fer + 1 four + 3 pierres lisses)."},{"n":"Forgeron d'outils","c":"Métier","p":"villageois.html","d":"Bloc de métier : la table de forge (2 fer + 4 planches)."},{"n":"Forgeron d'armes","c":"Métier","p":"villageois.html","d":"Bloc de métier : la meule (2 bâtons + 1 dalle de pierre + 2 planches)."},{"n":"Clerc (prêtre)","c":"Métier","p":"villageois.html","d":"Bloc de métier : l'alambic (1 bâton de Blaze + 3 pierres)."},{"n":"Cartographe","c":"Métier","p":"villageois.html","d":"Bloc de métier : la table de cartographie (2 papiers + 4 planches)."},{"n":"Fléchier","c":"Métier","p":"villageois.html","d":"Bloc de métier : l'établi à flèches / fletching table (2 silex + 4 planches)."},{"n":"Berger","c":"Métier","p":"villageois.html","d":"Bloc de métier : le métier à tisser (2 ficelles + 2 planches)."},{"n":"Boucher","c":"Métier","p":"villageois.html","d":"Bloc de métier : le fumoir (4 bûches + 1 four)."},{"n":"Pêcheur","c":"Métier","p":"villageois.html","d":"Bloc de métier : le tonneau (6 planches + 2 dalles)."},{"n":"Tanneur","c":"Métier","p":"villageois.html","d":"Bloc de métier : le chaudron (7 lingots de fer)."},{"n":"Maçon","c":"Métier","p":"villageois.html","d":"Bloc de métier : le tailleur de pierre (1 fer + 3 pierres)."},{"n":"Villageois sans métier / Idiot (nitwit)","c":"Métier","p":"villageois.html","d":"Le villageois sans métier prend un métier si vous lui donnez un bloc. L'idiot (tenue verte) n'en prendra JAMAIS."},{"n":"Plaines","c":"Biome","p":"biomes.html","d":"Le biome le plus courant : herbe plate, quelques chênes, fleurs éparses."},{"n":"Forêt / Forêt de bouleaux / Forêt de fleurs","c":"Biome","p":"biomes.html","d":"Couverture dense de chênes ou de bouleaux ; la forêt de fleurs est une variante rare."},{"n":"Forêt sombre","c":"Biome","p":"biomes.html","d":"Chênes noirs si denses que le sol reste dans l'obscurité même en plein jour."},{"n":"Forêt pâle (Pale Garden)","c":"Biome","p":"biomes.html","d":"Variante blafarde de la forêt sombre : chênes pâles, mousse grise, aucun animal."},{"n":"Cerisaie (Cherry Grove)","c":"Biome","p":"biomes.html","d":"Sur les versants de montagne : arbres roses, herbe claire, pétales au sol."},{"n":"Marais / Marais de mangrove","c":"Biome","p":"biomes.html","d":"Eau stagnante, chênes couverts de lianes, argile au fond de l'eau."},{"n":"Jungle","c":"Biome","p":"biomes.html","d":"Végétation très dense, arbres géants, bambouseraies, cours d'eau."},{"n":"Désert","c":"Biome","p":"biomes.html","d":"Sable à perte de vue, cactus, aucune pluie."},{"n":"Badlands / Mesa","c":"Biome","p":"biomes.html","d":"Plateaux de terre cuite colorée en strates, très rares à générer."},{"n":"Savane","c":"Biome","p":"biomes.html","d":"Herbe jaune, acacias aux formes tordues, terrain vallonné."},{"n":"Champs de champignons","c":"Biome","p":"biomes.html","d":"Île isolée en plein océan, sol de mycélium, champignons géants."},{"n":"Taïga / Vieille taïga","c":"Biome","p":"biomes.html","d":"Sapins, fougères, sol souvent couvert de podzol dans les vieilles taïgas."},{"n":"Plaines enneigées / Pics glacés","c":"Biome","p":"biomes.html","d":"Neige permanente, lacs gelés, pics de glace compactée dans la variante extrême."},{"n":"Montagnes (versants, pics, bosquets)","c":"Biome","p":"biomes.html","d":"Reliefs au-dessus de Y 130 : pierre nue, neige, bosquets boisés."},{"n":"Océans (chaud, tiède, froid, gelé)","c":"Biome","p":"biomes.html","d":"Selon la température : récifs coralliens en océan chaud, kelp en océan froid."},{"n":"Océan profond & monument","c":"Biome","p":"biomes.html","d":"Fonds à Y 30 et moins ; le monument océanique s'y génère en prismarine."},{"n":"Rivière","c":"Biome","p":"biomes.html","d":"Cours d'eau traversant tous les biomes terrestres."},{"n":"Grottes luxuriantes","c":"Biome","p":"biomes.html","d":"Repérables en surface grâce aux azalées : creusez sous un azalée, la grotte est en dessous."},{"n":"Grottes de dripstone","c":"Biome","p":"biomes.html","d":"Vastes cavités hérissées de stalactites et de stalagmites."},{"n":"Deep Dark & Cité antique","c":"Biome","p":"biomes.html","d":"Sous les montagnes, généralement sous Y 0. Sol de sculk, silence total."},{"n":"Vallée du sable des âmes","c":"Biome","p":"biomes.html","d":"Vastes plaines de sable des âmes, squelettes en quantité, ghasts nombreux."},{"n":"Forêt écarlate / déformée","c":"Biome","p":"biomes.html","d":"Forêts de champignons géants rouges (écarlate) ou bleus (déformée)."},{"n":"Deltas de basalte","c":"Biome","p":"biomes.html","d":"Champs de basalte et de blackstone, lacs de lave, cendres en suspension."},{"n":"Étendue du Nether (Nether Wastes)","c":"Biome","p":"biomes.html","d":"Le biome classique du Nether : netherrack rouge, lacs de lave, grottes ouvertes."},{"n":"Île centrale de l'End","c":"Biome","p":"biomes.html","d":"L'île d'arrivée : obsidienne, tours à cristaux, le dragon."},{"n":"Îles extérieures de l'End","c":"Biome","p":"biomes.html","d":"Au-delà de la passerelle : îles de pierre de l'End, arbres à chorus, cités."},{"n":"Grottes de soufre (Sulfur Caves)","c":"Biome","p":"biomes.html","d":"Biome du Surworld. Les règles de surface de worldgen/noise_settings/overworld.json y remplacent la pierre par du cinabre ou du soufre selon "},{"n":"Village de plaines","c":"Structure","p":"structures.html","d":"Plaines, prairies et bords de rivière, entre Y 62 et 80. Bâti en chêne et pierre, avec des champs de blé, carottes, pommes de terre et bette"},{"n":"Village du désert","c":"Structure","p":"structures.html","d":"Déserts uniquement, souvent au bord d'un temple du désert ou d'un puits. Maisons en grès et grès taillé, toits plats, terrasses ; les champs"},{"n":"Village de savane","c":"Structure","p":"structures.html","d":"Savanes et plateaux de savane. Construit en acacia, avec des toits en terrasses et beaucoup de clôtures ; le relief y est plat, ce qui en fa"},{"n":"Village de taïga","c":"Structure","p":"structures.html","d":"Taïgas et vieilles taïgas. Maisons en sapin, grandes et hautes, souvent avec un sous-sol ou un grenier ; des citrouilles et des buissons de "},{"n":"Village de toundra enneigée","c":"Structure","p":"structures.html","d":"Plaines enneigées et pentes enneigées. Petits villages compacts en sapin, avec de la neige et de la glace ; c'est le type de village le moin"},{"n":"Temple du désert","c":"Structure","p":"structures.html","d":"Pyramide de grès dans les déserts, à moitié enfouie dans le sable, repérable à ses deux tours orange. Le sol de la salle centrale porte un m"},{"n":"Temple de la jungle","c":"Structure","p":"structures.html","d":"Jungles et jungles denses, en pierre et pierre moussue, souvent noyé dans la végétation et difficile à repérer depuis le sol. Trois niveaux "},{"n":"Hutte de sorcière","c":"Structure","p":"structures.html","d":"Marais et marais de mangrove, sur pilotis au-dessus de l'eau. Petite cabane en sapin avec un chaudron, un établi et un champignon en pot ; u"},{"n":"Manoir des bois","c":"Structure","p":"structures.html","d":"Uniquement en forêt sombre, et très loin : souvent plusieurs milliers de blocs du point de départ. La carte de l'explorateur des bois, achet"},{"n":"Avant-poste de pillards","c":"Structure","p":"structures.html","d":"Dans tous les biomes où les villages génèrent, souvent à quelques centaines de blocs d'un village. Grande tour en chêne noir et pierre, ento"},{"n":"Igloo","c":"Structure","p":"structures.html","d":"Plaines enneigées, taïgas enneigées et pentes enneigées. Petit dôme de neige avec un lit, un four et un établi ; environ un igloo sur deux c"},{"n":"Puits du désert","c":"Structure","p":"structures.html","d":"Déserts, isolé au milieu des dunes. Petite construction de grès de 4×4 avec une source d'eau au centre : rare, et facile à manquer depuis le"},{"n":"Ruines de sentier","c":"Structure","p":"structures.html","d":"Enterrées sous les taïgas, jungles, forêts de bouleaux, marais de mangrove et plaines enneigées. Seul un petit dôme de terre battue ou quelq"},{"n":"Portail ruiné (Surworld)","c":"Structure","p":"structures.html","d":"Partout dans le Surworld, en surface comme enfoui sous terre ou sous l'eau, à n'importe quelle altitude. Cadre d'obsidienne incomplet, entou"},{"n":"Donjon (salle du générateur)","c":"Structure","p":"structures.html","d":"Petites salles de pierre et de pierre moussue (7×7 ou 9×9 avec les murs), enfouies partout entre le fond du monde et la surface, souvent bra"},{"n":"Mine abandonnée","c":"Structure","p":"structures.html","d":"Réseaux de galeries boisées avec rails et supports, entre le fond du monde et Y 30 environ. Dans les badlands, une variante en chêne noir gé"},{"n":"Forteresse (Stronghold)","c":"Structure","p":"structures.html","d":"Enfouie profondément, en anneaux concentriques autour de l'origine du monde : les trois premières forteresses se situent à environ 1 280 à 2"},{"n":"Cité antique","c":"Structure","p":"structures.html","d":"Uniquement dans le biome Deep Dark, autour de Y -52, sous les massifs montagneux et les hauts plateaux. Immense complexe de pierre des profo"},{"n":"Chambres d'épreuve","c":"Structure","p":"structures.html","d":"Grands complexes de tuf et de cuivre dans la couche de pierre des profondeurs, sous la plupart des biomes du Surworld. Une chambre se reconn"},{"n":"Géode d'améthyste","c":"Structure","p":"structures.html","d":"Poche sphérique creuse entre le fond du monde et Y 30 environ, dans tous les biomes, souvent sous les océans. Trois couches : basalte lisse "},{"n":"Fosse de fossiles","c":"Structure","p":"structures.html","d":"Enfouie profondément sous les déserts, les marais et leurs variantes, dans la couche de pierre ou de pierre des profondeurs. Grande structur"},{"n":"Monument océanique","c":"Structure","p":"structures.html","d":"Océans profonds (toutes variantes), posé sur le fond, entre Y 39 et 61 environ. Immense bâtiment de prismarine visible de loin grâce à ses l"},{"n":"Épave","c":"Structure","p":"structures.html","d":"Au fond de tous les océans, parfois échouée sur une plage ou à moitié ensablée. Le navire génère droit, penché ou retourné, et il lui manque"},{"n":"Ruines sous-marines","c":"Structure","p":"structures.html","d":"Amas de bâtiments ruinés sur le fond marin, en deux familles : ruines froides en briques de pierre (océans tempérés, froids et gelés) et rui"},{"n":"Trésor enfoui","c":"Structure","p":"structures.html","d":"Un unique coffre enterré sous le sable, le gravier ou la pierre d'une plage ou d'un fond marin. Introuvable sans la carte au trésor obtenue "},{"n":"Forteresse du Nether","c":"Structure","p":"structures.html","d":"Traverse le Nether en longues bandes traversant plusieurs biomes, reconnaissable de très loin à ses ponts de briques du Nether au-dessus des"},{"n":"Portail ruiné (Nether)","c":"Structure","p":"structures.html","d":"Dans tous les biomes du Nether, souvent accroché à une falaise, en surplomb d'une mer de lave ou noyé dans le netherrack. Même butin que son"},{"n":"Bastion — salle du trésor","c":"Structure","p":"structures.html","d":"Variante de bastion la plus recherchée : une grande construction de pierre noire dont le cœur est une salle à or, gardée par plusieurs pigli"},{"n":"Bastion — pont","c":"Structure","p":"structures.html","d":"Bastion organisé autour d'un immense pont de pierre noire enjambant le vide ou une mer de lave, avec une rampe à chaque extrémité et une têt"},{"n":"Bastion — écuries de hoglins","c":"Structure","p":"structures.html","d":"Bastion en forme de grande halle ouverte avec des rampes et des enclos où les piglins parquent des hoglins. On le reconnaît aux enclos clôtu"},{"n":"Bastion — unités d'habitation","c":"Structure","p":"structures.html","d":"Bastion en forme de tours d'habitation empilées, reliées par des passerelles et des escaliers étroits : la variante la plus labyrinthique, a"},{"n":"Cité de l'End","c":"Structure","p":"structures.html","d":"Uniquement sur les îles extérieures de l'End, au-delà du vide qui entoure l'île centrale : on y accède par une passerelle de l'End (après la"},{"n":"Navire de l'End","c":"Structure","p":"structures.html","d":"Vaisseau flottant à côté de certaines cités de l'End seulement, en général à hauteur de la plus haute tour et légèrement à l'écart. Il faut "},{"n":"C'est chaud (Hot Stuff)","c":"Succès","p":"succes.html","d":"Remplir un seau de lave. Le clic droit doit viser une source de lave, pas un courant."},{"n":"Le défi du seau d'eau glacée (Ice Bucket Challenge)","c":"Succès","p":"succes.html","d":"Obtenir un bloc d'obsidienne dans son inventaire."},{"n":"Des diamants ! (Diamonds!)","c":"Succès","p":"succes.html","d":"Récupérer un diamant, quelle qu'en soit la provenance."},{"n":"Il faut creuser plus profond (We Need to Go Deeper)","c":"Succès","p":"succes.html","d":"Construire un portail du Nether, l'allumer et le franchir."},{"n":"Enchanteur (Enchanter)","c":"Succès","p":"succes.html","d":"Fabriquer une table d'enchantement et l'utiliser pour enchanter un objet."},{"n":"Couvert de diamants (Cover Me with Diamonds)","c":"Succès","p":"succes.html","d":"Obtenir UNE seule pièce d'armure en diamant — le succès se valide sur n'importe laquelle des quatre, et il n'est même pas nécessaire de la p"},{"n":"Docteur zombie (Zombie Doctor)","c":"Succès","p":"succes.html","d":"Affaiblir puis soigner un villageois zombifié."},{"n":"À vue d'œil (Eye Spy)","c":"Succès","p":"succes.html","d":"Pénétrer dans une forteresse (stronghold)."},{"n":"La Fin ? (The End?)","c":"Succès","p":"succes.html","d":"Franchir le portail de l'End dans la salle du portail d'une forteresse."},{"n":"Une terrible forteresse (A Terrible Fortress)","c":"Succès","p":"succes.html","d":"Entrer dans une forteresse du Nether."},{"n":"Dans le feu (Into Fire)","c":"Succès","p":"succes.html","d":"Récupérer un bâton de blaze."},{"n":"Brasserie locale (Local Brewery)","c":"Succès","p":"succes.html","d":"Récupérer une potion dans un alambic."},{"n":"Retour à l'envoyeur (Return to Sender)","c":"Succès","p":"succes.html","d":"Tuer un ghast avec sa propre boule de feu."},{"n":"Alliance difficile (Uneasy Alliance)","c":"Succès","p":"succes.html","d":"Ramener un ghast dans le Surworld et l'y tuer."},{"n":"C'était le bon temps (Those Were the Days)","c":"Succès","p":"succes.html","d":"Entrer dans un bastion."},{"n":"Caché dans les profondeurs (Hidden in the Depths)","c":"Succès","p":"succes.html","d":"Obtenir un bloc de débris antiques."},{"n":"Couvert de débris (Cover Me in Debris)","c":"Succès","p":"succes.html","d":"Porter simultanément les quatre pièces d'armure en netherite."},{"n":"Squelette effrayant (Spooky Scary Skeleton)","c":"Succès","p":"succes.html","d":"Obtenir une tête de squelette wither."},{"n":"Les hauteurs du Wither (Withering Heights)","c":"Succès","p":"succes.html","d":"Invoquer le Wither."},{"n":"Balisateur (Beaconator)","c":"Succès","p":"succes.html","d":"Construire une balise à pleine puissance : pyramide complète de quatre niveaux sous la balise."},{"n":"Comment on en est arrivés là ? (How Did We Get Here?)","c":"Succès","p":"succes.html","d":"Avoir tous les effets de statut obtenables en même temps."},{"n":"Libérer la Fin (Free the End)","c":"Succès","p":"succes.html","d":"Tuer le dragon de l'End."},{"n":"Il te faudrait un bonbon à la menthe (You Need a Mint)","c":"Succès","p":"succes.html","d":"Récupérer du souffle du dragon dans une fiole en verre."},{"n":"La génération suivante (The Next Generation)","c":"Succès","p":"succes.html","d":"Ramasser l'œuf de dragon apparu au sommet du portail de sortie."},{"n":"La Fin... encore... (The End... Again...)","c":"Succès","p":"succes.html","d":"Réinvoquer le dragon de l'End."},{"n":"Escapade lointaine (Remote Getaway)","c":"Succès","p":"succes.html","d":"Franchir une passerelle de l'End (end gateway) vers les îles extérieures."},{"n":"La cité au bout du monde (The City at the End of the Game)","c":"Succès","p":"succes.html","d":"Entrer dans une cité de l'End."},{"n":"Le ciel est la limite (Sky's the Limit)","c":"Succès","p":"succes.html","d":"Récupérer une paire d'élytres."},{"n":"Belle vue d'ici (Great View From Up Here)","c":"Succès","p":"succes.html","d":"Monter de 50 blocs sous l'effet de Lévitation infligé par un shulker."},{"n":"Exil volontaire (Voluntary Exile)","c":"Succès","p":"succes.html","d":"Tuer un capitaine de raid : un pillard portant une bannière de mauvais présage sur la tête."},{"n":"Héros du village (Hero of the Village)","c":"Succès","p":"succes.html","d":"Remporter un raid : vaincre toutes les vagues de pillards attaquant un village."},{"n":"Post-mortel (Postmortal)","c":"Succès","p":"succes.html","d":"Utiliser un totem d'immortalité pour survivre à une mort certaine."},{"n":"Duel de snipers (Sniper Duel)","c":"Succès","p":"succes.html","d":"Tuer un squelette à 50 blocs de distance ou plus, à l'arc."},{"n":"Arbalistique (Arbalistic)","c":"Succès","p":"succes.html","d":"Tuer cinq créatures d'espèces différentes d'un seul tir d'arbalète."},{"n":"Très très effrayant (Very Very Frightening)","c":"Succès","p":"succes.html","d":"Frapper un villageois avec un trident à Canalisation pendant un orage."},{"n":"Discrétion 100 (Sneak 100)","c":"Succès","p":"succes.html","d":"Passer accroupi à côté d'un capteur sculk ou d'un hurleur sans qu'il vous détecte."},{"n":"Sous clé (Under Lock and Key) / Coffre-fort sinistre (Revaulting)","c":"Succès","p":"succes.html","d":"Ouvrir un coffre-fort avec une clé d'épreuve, puis un coffre-fort sinistre avec une clé sinistre."},{"n":"Surpuissance (Over-Overkill)","c":"Succès","p":"succes.html","d":"Infliger 100 points de dégâts en un seul coup de masse (soit 50 cœurs)."},{"n":"Monstres chassés (Monsters Hunted)","c":"Succès","p":"succes.html","d":"Tuer au moins un exemplaire de chaque créature hostile du jeu."},{"n":"L'heure de l'aventure (Adventuring Time)","c":"Succès","p":"succes.html","d":"Visiter tous les biomes du Surworld (plus de quarante)."},{"n":"Deux par deux (Two by Two)","c":"Succès","p":"succes.html","d":"Reproduire chaque espèce d'animal reproductible du jeu."},{"n":"Un régime équilibré (A Balanced Diet)","c":"Succès","p":"succes.html","d":"Manger tous les aliments du jeu, y compris ceux qui vous rendent malade."},{"n":"Un catalogue complet (A Complete Catalogue)","c":"Succès","p":"succes.html","d":"Apprivoiser les onze variantes de chat."},{"n":"Soyez notre invité (Bee Our Guest)","c":"Succès","p":"succes.html","d":"Remplir une bouteille de miel dans une ruche pleine sans mettre les abeilles en colère."},{"n":"Pêche tactique (Tactical Fishing)","c":"Succès","p":"succes.html","d":"Capturer un poisson avec un seau d'eau (et non avec une canne)."},{"n":"Le pouvoir guérisseur de l'amitié (The Healing Power of Friendship)","c":"Succès","p":"succes.html","d":"Faire équipe avec un axolotl et gagner un combat : recevoir l'effet Régénération d'un axolotl qui vient de tuer une cible."},{"n":"Tu as un ami en moi (You've Got a Friend in Me)","c":"Succès","p":"succes.html","d":"Recevoir un objet rapporté par un allay — le succès ne demande PAS de le dupliquer, contrairement à ce qu'on lit souvent."},{"n":"Dévouement sérieux (Serious Dedication)","c":"Succès","p":"succes.html","d":"Améliorer une houe en netherite sur la table de forge."},{"n":"Toute la meute (The Whole Pack)","c":"Succès","p":"succes.html","d":"Apprivoiser une variante de chaque pelage de loup."},{"n":"Chêne","c":"Bloc","p":"blocs.html","d":"Plaines, forêts, marais, montagnes : le bois le plus commun du jeu. Une bûche donne 4 planches."},{"n":"Épicéa","c":"Bloc","p":"blocs.html","d":"Taïgas et versants de montagne. Les vieilles taïgas portent des épicéas 2×2 qui donnent des piles entières de bûches."},{"n":"Bouleau","c":"Bloc","p":"blocs.html","d":"Forêts de bouleaux et forêts tempérées, partout en zone modérée."},{"n":"Bois de jungle (acajou)","c":"Bloc","p":"blocs.html","d":"Jungles et bambouseraies uniquement. Les arbres géants 2×2 fournissent des bûches en masse."},{"n":"Acacia","c":"Bloc","p":"blocs.html","d":"Savanes uniquement. Les arbres poussent en escalier, la récolte demande de grimper."},{"n":"Chêne noir","c":"Bloc","p":"blocs.html","d":"Forêts sombres, toujours en arbres 2×2 : c'est le bois qui se récolte le plus vite du jeu."},{"n":"Mangrove","c":"Bloc","p":"blocs.html","d":"Marais de mangrove. La propagule se replante partout, y compris dans l'eau."},{"n":"Cerisier","c":"Bloc","p":"blocs.html","d":"Cerisaies, sur les versants de montagne tempérés."},{"n":"Chêne pâle","c":"Bloc","p":"blocs.html","d":"Forêt pâle (Pale Garden) uniquement, une variante blafarde et rare de la forêt sombre."},{"n":"Bambou","c":"Bloc","p":"blocs.html","d":"Jungles et bambouseraies. Le bambou repousse tout seul : c'est le seul « bois » entièrement automatisable sans ferme à arbres."},{"n":"Bois écarlate et bois difforme (Nether)","c":"Bloc","p":"blocs.html","d":"Forêts écarlate (rouge) et déformée (turquoise) du Nether. La poudre d'os sur du nylium fait repousser des champignons géants."},{"n":"Pierre, pierre taillée et pierre lisse","c":"Bloc","p":"blocs.html","d":"Sous vos pieds partout. La pierre taillée se cuit en pierre, et la pierre se recuit en pierre lisse."},{"n":"Briques de pierre","c":"Bloc","p":"blocs.html","d":"4 pierres à l'établi. On les trouve toutes faites dans les igloos, les ruines océaniques et les portails ruinés."},{"n":"Andésite, diorite et granite","c":"Bloc","p":"blocs.html","d":"Filons énormes dans toutes les grottes. 1 diorite + 1 pierre taillée = 2 andésites ; 1 diorite + 1 quartz = 2 granites."},{"n":"Pierre des profondeurs (deepslate)","c":"Bloc","p":"blocs.html","d":"Sous Y 8 environ. À la pioche elle donne de la pierre des profondeurs taillée ; le bloc lisse et orientable exige le Toucher de soie."},{"n":"Tuf","c":"Bloc","p":"blocs.html","d":"Autour des filons de minerai et dans les grottes profondes, en très gros amas."},{"n":"Grès et grès rouge","c":"Bloc","p":"blocs.html","d":"4 sables = 1 grès. Le grès rouge vient du sable rouge des badlands. Un désert en fournit sans aucune limite."},{"n":"Quartz","c":"Bloc","p":"blocs.html","d":"Minerai de quartz du Nether, très abondant, surtout dans les deltas de basalte. 4 quartz = 1 bloc."},{"n":"Cuivre et ses états d'oxydation","c":"Bloc","p":"blocs.html","d":"Filons géants dans les grottes de dripstone et vers Y 48 ; les noyés en laissent tomber, la ressource est donc renouvelable. 9 lingots = 1 b"},{"n":"Terre cuite","c":"Bloc","p":"blocs.html","d":"Cuisez un bloc d'argile. Les badlands en offrent des montagnes entières, déjà colorées en strates."},{"n":"Briques, argile et briques de boue","c":"Bloc","p":"blocs.html","d":"Argile au fond des rivières et des grottes luxuriantes : 1 bloc = 4 boules, cuites en briques, 4 briques = 1 bloc. La boue s'obtient en vers"},{"n":"Mousse, azalée et blocs végétaux","c":"Bloc","p":"blocs.html","d":"Grottes luxuriantes, ou marchand ambulant. La poudre d'os sur un bloc de mousse le propage et convertit la pierre alentour."},{"n":"Feuillages","c":"Bloc","p":"blocs.html","d":"Sur tous les arbres ; il faut des cisailles (ou le Toucher de soie) pour récupérer le bloc."},{"n":"Foin et blocs de champignon","c":"Bloc","p":"blocs.html","d":"9 blés = 1 botte de foin (récupérable en blé). Les blocs de champignon se récoltent au Toucher de soie sur les champignons géants."},{"n":"Béton et poudre de béton","c":"Bloc","p":"blocs.html","d":"4 sables + 4 graviers + 1 teinture = 8 poudres. La poudre durcit dès qu'elle touche de l'eau."},{"n":"Terre cuite vernissée","c":"Bloc","p":"blocs.html","d":"Cuisez une terre cuite colorée : chacune des 16 couleurs donne un motif différent."},{"n":"Laine et tapis","c":"Bloc","p":"blocs.html","d":"Tondez des moutons — teindre un mouton rend sa laine colorée renouvelable à l'infini. Sinon, 4 ficelles = 1 laine."},{"n":"Verre, vitres et verre teinté","c":"Bloc","p":"blocs.html","d":"Cuisez du sable. 6 verres = 16 vitres ; 8 verres + 1 teinture = 8 verres colorés ; 4 éclats d'améthyste autour d'un verre = 1 verre teinté."},{"n":"Netherrack et briques du Nether","c":"Bloc","p":"blocs.html","d":"Le Nether entier. Le netherrack se cuit en brique du Nether ; 4 briques = 1 bloc."},{"n":"Pierre noire (blackstone)","c":"Bloc","p":"blocs.html","d":"Deltas de basalte et bastions. C'est la roche la plus sombre du jeu, plus noire encore que la pierre des profondeurs."},{"n":"Basalte, blocs des âmes et magma","c":"Bloc","p":"blocs.html","d":"Deltas de basalte, vallées du sable des âmes. Le basalte se fabrique aussi à l'infini avec de la lave, de la glace bleue et de la terre des "},{"n":"Pierre de l'End","c":"Bloc","p":"blocs.html","d":"Toutes les îles de l'End. 4 pierres de l'End = 4 briques de l'End."},{"n":"Purpur","c":"Bloc","p":"blocs.html","d":"Cités de l'End. Les fruits du chorus cuits donnent des fruits éclatés, et 4 fruits éclatés = 4 blocs : c'est la seule ressource violette ill"},{"n":"Prismarine","c":"Bloc","p":"blocs.html","d":"Monuments océaniques. 4 éclats = 1 prismarine ; 9 éclats = 4 briques ; 8 éclats + poche d'encre = 8 prismarines sombres."},{"n":"Glace, neige et blancs froids","c":"Bloc","p":"blocs.html","d":"Biomes glacés. 9 glaces = 1 glace compactée, 9 compactées = 1 glace bleue. La calcite vient des géodes d'améthyste."},{"n":"Pierre lumineuse et lanterne marine","c":"Bloc","p":"blocs.html","d":"La pierre lumineuse pend au plafond du Nether (4 poussières = 1 bloc) ; la lanterne marine se fabrique avec 4 éclats et 5 cristaux de prisma"},{"n":"Froglights, shroomlight et lumières organiques","c":"Bloc","p":"blocs.html","d":"Le shroomlight pousse dans les forêts du Nether ; les froglights s'obtiennent quand une grenouille avale un petit cube de magma."},{"n":"Bougies, lanternes et lumières d'appoint","c":"Bloc","p":"blocs.html","d":"Bougie : 1 rayon de miel + 1 ficelle, teintable en 16 couleurs. Lanterne : 8 pépites de fer + 1 torche. Le lichen luisant se récolte aux cis"},{"n":"Table et chaises","c":"Déco","p":"deco.html","d":"Salle à manger, cuisine, taverne, salle de conseil. C'est le meuble qui fixe la hauteur de lecture de toute la pièce : tout le reste se cale"},{"n":"Banc, canapé et fauteuil","c":"Déco","p":"deco.html","d":"Salon, taverne, salle d'attente, place publique. Un assis pour plusieurs personnes : c'est ce qui distingue une pièce meublée d'une pièce re"},{"n":"Lit aménagé","c":"Déco","p":"deco.html","d":"Toute chambre. Un lit posé seul contre un mur reste un objet de jeu ; entouré, il devient un meuble."},{"n":"Bureau, étagère et bibliothèque murale","c":"Déco","p":"deco.html","d":"Cabinet de travail, tour de mage, comptoir de scribe, coin bureau d'une chambre."},{"n":"Armoire, penderie et coffres encastrés","c":"Déco","p":"deco.html","d":"Chambre, réserve, vestibule, arrière-boutique. Ranger sans transformer la pièce en entrepôt."},{"n":"Comptoir, plan de travail et évier","c":"Déco","p":"deco.html","d":"Cuisine, taverne, laboratoire, boutique. Le comptoir est le meuble le plus long de la maison : c'est lui qui donne son rythme à la pièce."},{"n":"Cheminée et conduit de fumée","c":"Déco","p":"deco.html","d":"Salon, cuisine, salle commune, chambre de maître. C'est l'élément qui organise toute une pièce : le mobilier se tourne vers lui."},{"n":"Établi habillé et postes d'artisanat","c":"Déco","p":"deco.html","d":"Atelier, forge, arrière-cour, coin technique d'une base. Les blocs fonctionnels sont laids posés seuls : il faut les monter en meuble."},{"n":"Tapis, rideaux et textiles","c":"Déco","p":"deco.html","d":"Toutes les pièces habitées. Le textile est ce qui casse la dureté minérale d'un intérieur, et le seul moyen d'ajouter de la couleur sans cha"},{"n":"Cuisine et salle à manger","c":"Déco","p":"deco.html","d":"Rez-de-chaussée, de préférence contre un mur extérieur pour la fenêtre au-dessus de l'évier et la souche de cheminée."},{"n":"Chambre","c":"Déco","p":"deco.html","d":"Étage ou fond de maison, jamais au passage. Une chambre doit être la pièce la plus petite et la plus basse de la maison."},{"n":"Salon","c":"Déco","p":"deco.html","d":"Cœur de la maison, en général de plain-pied avec l'entrée et ouvert sur la salle à manger."},{"n":"Salle de bains","c":"Déco","p":"deco.html","d":"Petite pièce attenante à la chambre, ou sous un escalier. Trois blocs sur quatre suffisent."},{"n":"Atelier, cave et réserve","c":"Déco","p":"deco.html","d":"Sous-sol, appentis, arrière-cour. Toutes les pièces où l'on travaille et où l'on stocke, et qui doivent le montrer."},{"n":"Salle du trône","c":"Déco","p":"deco.html","d":"Fond du donjon ou du grand hall, dans l'axe exact de la porte d'entrée. Le seul cas où la symétrie totale est le bon choix."},{"n":"Bibliothèque et cabinet de travail","c":"Déco","p":"deco.html","d":"Étage noble, tour, aile d'un manoir. Une pièce entièrement définie par ses murs : le mobilier y est presque secondaire."},{"n":"Serre intérieure","c":"Déco","p":"deco.html","d":"Aile vitrée, véranda, dernier étage d'une tour, cour couverte. Une pièce qui n'a besoin ni de mobilier ni de couleur ajoutée."},{"n":"Entrée et vestibule","c":"Déco","p":"deco.html","d":"Derrière la porte d'entrée. Deux à quatre blocs de profondeur, souvent la pièce la plus négligée alors qu'elle est vue en premier."},{"n":"Jardin, parterres et potager","c":"Déco","p":"deco.html","d":"Autour de toute maison. Un bâtiment posé sur une pelouse plate a l'air d'un objet lâché ; le jardin est ce qui le raccroche au sol."},{"n":"Allée, pavage et banc public","c":"Déco","p":"deco.html","d":"Entre la porte et la route, dans une cour, sur une place de village. Le sol est la surface qu'on regarde le plus et celle qu'on travaille le"},{"n":"Clôture, portail et haie","c":"Déco","p":"deco.html","d":"Limites de parcelle, enclos, cour de ferme, entrée de domaine. Ce qui transforme un terrain en propriété."},{"n":"Puits et fontaine","c":"Déco","p":"deco.html","d":"Place de village, cour de ferme, cloître, jardin clos. Le point autour duquel tout le reste s'organise naturellement."},{"n":"Terrasse et pergola","c":"Déco","p":"deco.html","d":"Contre la façade sud, au bord de l'eau, sur un toit plat. La pièce extérieure qui prolonge le salon."},{"n":"Appontement et berge","c":"Déco","p":"deco.html","d":"Bord de lac, de rivière ou de mer, au pied d'un village de pêcheurs ou d'un entrepôt."},{"n":"Ruines décoratives","c":"Déco","p":"deco.html","d":"À l'écart d'un bâtiment neuf, dans une clairière, au bord d'une route. Le moyen le plus rapide de donner un passé à un lieu."},{"n":"Éclairage caché","c":"Déco","p":"deco.html","d":"Partout où une source visible casserait le style : intérieur soigné, façade moderne, sol de couloir, corniche de plafond."},{"n":"Lanternes suspendues, chaînes et lustre","c":"Déco","p":"deco.html","d":"Grande salle, couloir, halle, escalier, extérieur couvert. Dès que le plafond est à plus de 4 blocs, la lumière doit descendre."},{"n":"Bougies et chandeliers","c":"Déco","p":"deco.html","d":"Table, chevet, autel, cave, chapelle. La seule source qui éclaire peu par construction — ce qui est exactement le but."},{"n":"Feu de camp d'intérieur","c":"Déco","p":"deco.html","d":"Âtre, forge, campement, salle commune, brasier de salle du trône."},{"n":"Lampes commutables et éclairage extérieur","c":"Déco","p":"deco.html","d":"Façade, rue, quai, cour, mais aussi tout intérieur qu'on veut pouvoir éteindre."},{"n":"Encadrement de fenêtre et volets","c":"Déco","p":"deco.html","d":"Toutes les baies, dedans comme dehors. Une vitre posée à ras du mur est le signe le plus reconnaissable d'une construction bâclée."},{"n":"Corniche, plinthe et poutre apparente","c":"Déco","p":"deco.html","d":"Jonction mur-plafond, pied de mur, sous-face de plancher. Les trois lignes horizontales qui donnent une échelle à une pièce."},{"n":"Gouttière, descente et enseigne","c":"Déco","p":"deco.html","d":"Bas de toit, angles de façade, devanture de boutique, entrée d'auberge. Les accessoires qui font qu'un bâtiment paraît utilisé."},{"n":"Pots, cadres, tonneaux et supports à armure","c":"Déco","p":"deco.html","d":"Rebords, coins de pièce, étals, réserves, halls d'entrée. Les petits objets qui remplissent les vides que le mobilier ne peut pas occuper."},{"n":"Marche, sprint et saut","c":"Transport","p":"transport.html","d":"Toutes les vitesses du jeu se comparent à celle-ci : avant d'investir dans un rail ou une élytre, sachez ce que vaut votre propre pas."},{"n":"Effet Rapidité","c":"Transport","p":"transport.html","d":"Le seul moyen d'accélérer la marche elle-même, en potion pour un trajet ou en balise pour un chantier."},{"n":"Glace, glace compactée et glace bleue au sol","c":"Transport","p":"transport.html","d":"Les trois glaces réduisent le frottement du sol : on accélère longtemps, et on ne freine plus du tout."},{"n":"Sable des âmes et Âme rapide","c":"Transport","p":"transport.html","d":"Le sol qui ralentit tout le monde peut devenir le plus rapide du jeu, avec le bon enchantement de bottes."},{"n":"Échelles, vignes et échafaudage","c":"Transport","p":"transport.html","d":"Trois façons de monter à pied, qui ne servent pas du tout aux mêmes moments : chantier, accès définitif, ou dépannage gratuit."},{"n":"Perle de l'Ender et fruit de chorus","c":"Transport","p":"transport.html","d":"Les deux seuls objets qui déplacent instantanément le joueur : l'un se vise, l'autre tire au hasard."},{"n":"Cheval : lire ses statistiques","c":"Transport","p":"transport.html","d":"Deux chevaux identiques à l'écran vont du simple au triple : tout se joue sur trois valeurs tirées au hasard à la naissance."},{"n":"Bêtes de somme : âne, mulet et lama","c":"Transport","p":"transport.html","d":"Trois montures lentes dont l'intérêt n'est pas la vitesse mais le nombre d'emplacements qu'elles emportent."},{"n":"Cochon et strider : les montures à perche","c":"Transport","p":"transport.html","d":"Deux montures dirigées de la même façon : une selle sur le dos, et une canne à pêche améliorée dans la main."},{"n":"Chameau","c":"Transport","p":"transport.html","d":"Grande monture des villages du désert : lente au pas, mais elle place le cavalier au-dessus de tout ce qui frappe au corps à corps."},{"n":"Le bateau hors de l'eau","c":"Transport","p":"transport.html","d":"Un bateau posé au sol reste pilotable : presque inutile à plat, il devient irremplaçable sur la glace et pour déplacer une créature."},{"n":"Les quatre rails et ce qu'ils coûtent","c":"Transport","p":"transport.html","d":"Une ligne complète ne se compose que de quatre pièces ; le budget se calcule avant de poser le premier bloc, pas après."},{"n":"Rails motorisés : espacement et pentes","c":"Transport","p":"transport.html","d":"Le rail motorisé ne rend pas le wagonnet plus rapide, il l'empêche de ralentir : tout le réglage tient dans son espacement."},{"n":"Wagonnet : conduite et limites","c":"Transport","p":"transport.html","d":"Le véhicule le plus lent à mettre en place du jeu, mais le seul qui monte tout seul et sans effort."},{"n":"Wagonnet-coffre et fret automatique","c":"Transport","p":"transport.html","d":"C'est là que le rail devient imbattable : une ligne qui transporte des objets pendant que vous faites autre chose."},{"n":"Station de départ et de retour","c":"Transport","p":"transport.html","d":"Une gare, c'est trois pièces : un rail motorisé éteint qui retient le wagonnet, un bouton qui l'alimente, un rail détecteur qui le renvoie."},{"n":"Bateau et bateau-coffre","c":"Transport","p":"transport.html","d":"L'objet le plus rentable du jeu : cinq planches pour aller nettement plus vite qu'en sprint, sans dépenser une seule cuisse de poulet."},{"n":"Autoroute de glace bleue en bateau","c":"Transport","p":"transport.html","d":"Un couloir de glace bleue parcouru en bateau est le déplacement le plus rapide du jeu hors élytre, et le seul qui reste fiable au Nether."},{"n":"Courants d'eau et colonnes de bulles","c":"Transport","p":"transport.html","d":"L'eau déplace gratuitement joueurs, objets et créatures : c'est la logistique la moins chère du jeu, à condition de connaître sa portée."},{"n":"Conduit : respirer et voir sous l'eau","c":"Transport","p":"transport.html","d":"Le conduit transforme un chantier sous-marin en chantier normal : plus d'apnée, plus de brouillard, plus de lenteur de minage."},{"n":"Nager vite : dauphin, trident, Agilité aquatique","c":"Transport","p":"transport.html","d":"La nage nue est plus lente que la marche ; trois solutions la rendent plus rapide qu'un sprint."},{"n":"Élytre : durabilité et entretien","c":"Transport","p":"transport.html","d":"L'élytre ne casse jamais vraiment : elle s'arrête à 1 point de durabilité et refuse simplement de s'ouvrir jusqu'à réparation."},{"n":"Fusées de feu d'artifice","c":"Transport","p":"transport.html","d":"La fusée est le seul carburant du vol : sa fabrication décide de la distance que vous pouvez parcourir dans une partie."},{"n":"Décoller sans montagne","c":"Transport","p":"transport.html","d":"On peut lancer un vol depuis un terrain parfaitement plat : il suffit d'un tremplin, d'une averse ou d'une poussée violente."},{"n":"Vol plané : altitude, angle et distance","c":"Transport","p":"transport.html","d":"Sans fusée, le vol est un échange : on convertit de la hauteur en distance, et l'angle décide du taux de change."},{"n":"Atterrir sans mourir","c":"Transport","p":"transport.html","d":"L'élytre ne protège de rien : la fin du vol tue bien plus souvent que le vol lui-même."},{"n":"Coordonnées et écran de débogage","c":"Transport","p":"transport.html","d":"Trois nombres suffisent à ne plus jamais être perdu ; encore faut-il savoir dans quel sens ils augmentent."},{"n":"Boussole, magnétite et boussole de réapparition","c":"Transport","p":"transport.html","d":"Trois boussoles différentes, qui pointent trois choses différentes : le spawn du monde, un bloc que vous avez posé, ou votre dernière mort."},{"n":"Carte, agrandissement et verrouillage","c":"Transport","p":"transport.html","d":"Une carte ne dessine que ce que vous avez parcouru en la tenant ouverte : c'est un carnet de terrain, pas un satellite."},{"n":"Marqueurs de bannière et murs de cartes","c":"Transport","p":"transport.html","d":"Le seul moyen d'inscrire un nom sur une carte, et donc de transformer un dessin en index consultable."},{"n":"Repères bâtis et signalétique","c":"Transport","p":"transport.html","d":"Un monde bien balisé se parcourt sans carte : ce sont vos constructions qui font office de panneaux indicateurs."},{"n":"Retrouver sa base après une mort","c":"Transport","p":"transport.html","d":"Le butin ne dépend pas de votre courage mais d'une seule variable : la distance que vous pouvez couvrir en cinq minutes."},{"n":"Abri de première nuit","c":"Plan","p":"plans.html","a":"abri","d":"À construire dans les dix premières minutes. Objectif : survivre à la nuit 1 avec un lit, un four et un coffre — rien de plus."},{"n":"Maison de colon 9 × 7","c":"Plan","p":"plans.html","a":"maison-bois","d":"La maison « qui tient toute la partie » : assez grande pour un atelier, assez simple pour être bâtie en une journée de jeu."},{"n":"Tour de guet / phare","c":"Plan","p":"plans.html","a":"tour","d":"Repère visible à 200 blocs, poste d'observation et point de récupération d'élytre. Sert aussi de cheminée de mine."},{"n":"Château fort — plan de masse 25 × 25","c":"Plan","p":"plans.html","a":"chateau","d":"Enceinte carrée, quatre tours d'angle, châtelet d'entrée au sud et donjon central 9 × 9. Le plan classique, compact et défendable."},{"n":"Donjon central (keep) 9 × 9","c":"Plan","p":"plans.html","a":"donjon-keep","d":"Le cœur du château : trois niveaux, escalier en colimaçon, salle du trône, salle des coffres et terrasse crénelée."},{"n":"Parcelle de culture 9 × 9","c":"Plan","p":"plans.html","a":"ferme-ble","d":"L'unité de base de toute agriculture : une source d'eau au centre hydrate exactement 9 × 9 blocs de terre labourée."},{"n":"Enclos d'élevage compartimenté","c":"Plan","p":"plans.html","a":"enclos","d":"Trois compartiments séparés (vaches, moutons, poulets) avec un couloir central : indispensable pour ne pas mélanger les espèces lors de la r"},{"n":"Grange à charpente apparente","c":"Plan","p":"plans.html","a":"grange","d":"Le bâtiment agricole de référence : grand volume, charpente visible, portes charretières, grenier à foin. Rend un village crédible instantan"},{"n":"Salle d'enchantement niveau 30","c":"Plan","p":"plans.html","a":"enchant","d":"La disposition optimale : exactement 15 bibliothèques autour de la table, à 2 blocs de distance, avec de l'air entre les deux."},{"n":"Portail du Nether sécurisé","c":"Plan","p":"plans.html","a":"portail","d":"Un portail non protégé est une porte ouverte : zombies-piglins, ghasts et hoglins traversent. Ce sas règle le problème des deux côtés."},{"n":"Entrepôt à tri automatique — module de base","c":"Plan","p":"plans.html","a":"stockage","d":"Un module de tri par type d'objet, à répliquer autant de fois que nécessaire. Les objets circulent dans une ligne d'entonnoirs et tombent da"},{"n":"Maison moderne 13 × 9","c":"Plan","p":"plans.html","a":"maison-moderne","d":"Volumes nets, toit-terrasse, grandes baies vitrées. Le style le plus simple à réussir : il ne pardonne rien sur les proportions, mais ne dem"},{"n":"Village complet — plan de masse 21 × 21","c":"Plan","p":"plans.html","a":"village","d":"Trame de rues, place centrale avec puits et cloche, douze parcelles bâties. Le plan qui transforme un tas de maisons en village crédible."},{"n":"Pont de pierre à arches","c":"Plan","p":"plans.html","a":"pont","d":"Franchit une rivière ou un ravin. La courbe des arches est ce qui distingue un pont d'une simple passerelle posée sur des piliers."},{"n":"Port et quai marchand","c":"Plan","p":"plans.html","a":"port","d":"Quai de pierre, deux pontons sur pilotis, entrepôt en retrait. Le point de départ de toute exploration maritime, et le meilleur endroit pour"},{"n":"Statue monumentale — creeper 20 blocs","c":"Plan","p":"plans.html","a":"statue","d":"Un repère visible de très loin. Le principe vaut pour n'importe quelle statue : on travaille en élévation (vue de face), pas en couches hori"},{"n":"Mine aménagée (branch mining à Y −59)","c":"Plan","p":"plans.html","a":"mine","d":"La méthode de minage la plus efficace du jeu : un tunnel principal, des branches tous les 3 blocs. Cette trame expose le maximum de blocs po"},{"n":"Base sous-marine — dôme de verre 13 × 13","c":"Plan","p":"plans.html","a":"sous-marine","d":"Une bulle d'air au fond de l'océan. Le chantier est difficile (respiration, vision, courants) mais le résultat est l'une des constructions l"},{"n":"Fort du Nether — base fortifiée 15 × 15","c":"Plan","p":"plans.html","a":"base-nether","d":"Un avant-poste autour de votre portail, à l'épreuve des ghasts et des piglins. C'est la tête de pont indispensable si vous comptez exploiter"},{"n":"Cathédrale — nef, transept et clocher","c":"Plan","p":"plans.html","a":"cathedrale","d":"Le chantier d'une partie entière : une nef de 9 blocs de large, un transept qui la coupe en croix, un chœur en abside et un clocher-porche. "},{"n":"Quartier médiéval — îlot mitoyen sur rue","c":"Plan","p":"plans.html","a":"quartier-medieval","d":"Deux rangées de maisons mitoyennes de part et d'autre d'une ruelle de 3 blocs. C'est le plan qui fait passer d'un « village de cubes espacés"},{"n":"Base creusée dans la montagne","c":"Plan","p":"plans.html","a":"base-montagne","d":"Un portail monumental taillé dans une falaise, un grand hall à colonnes et trois salles creusées au fond. La difficulté n'est pas de creuser"},{"n":"Maison dans les arbres — trois plateformes","c":"Plan","p":"plans.html","a":"maison-arbres","d":"Trois cabanes perchées à 8 blocs du sol, reliées par des passerelles en dalles. L'intérêt n'est pas la hauteur mais le trajet : on doit pouv"},{"n":"Colisée — arène à gradins circulaires","c":"Plan","p":"plans.html","a":"colisee","d":"Une arène de 13 blocs de diamètre entourée de deux rangs de gradins, deux loges d'honneur et deux tunnels d'entrée. Sert de zone de combat P"},{"n":"Ferme fortifiée — cour, mur et tour d'angle","c":"Plan","p":"plans.html","a":"ferme-fortifiee","d":"Une exploitation agricole entièrement close : corps de ferme au nord, grange et enclos au sud, potager, puits central et une tour d'angle qu"},{"n":"Auberge à deux étages avec écurie","c":"Plan","p":"plans.html","a":"auberge","d":"Salle commune et cuisine au rez-de-chaussée, quatre chambres à l'étage, écurie sur la cour. C'est le bâtiment public qui donne vie à un vill"},{"n":"Moulin à vent — corps, ailes et meule","c":"Plan","p":"plans.html","a":"moulin-vent","d":"Une tour tronconique en pierre coiffée d'une calotte en bois, avec une roue d'ailes de 13 blocs de diamètre et une meule au rez-de-chaussée."},{"n":"Serre / jardin d'hiver vitré","c":"Plan","p":"plans.html","a":"serre","d":"Une enveloppe entièrement vitrée sur un soubassement de pierre : quatre bacs de culture hydratés, une allée centrale et un toit à deux versa"},{"n":"Phare côtier sur récif","c":"Plan","p":"plans.html","a":"phare-recif","d":"Un fût de pierre à bandes claires planté sur un récif artificiel, avec une digue en muret, une galerie en encorbellement et un lanternon vit"},{"n":"Bibliothèque monumentale à mezzanine","c":"Plan","p":"plans.html","a":"bibliotheque","d":"Une salle unique de 13 blocs de haut, ceinturée de rayonnages sur deux niveaux, avec une mezzanine en U ouverte sur le vide central et un la"},{"n":"Forge de village — four, enclume et charbonnière","c":"Plan","p":"plans.html","a":"forge-village","d":"Un atelier ouvert sur la rue par un large auvent : batterie de fourneaux sous la hotte, enclume et bac de trempe au centre, réserve de charb"},{"n":"Halle de marché couverte","c":"Plan","p":"plans.html","a":"halle-marche","d":"Une charpente sur colonnade, sans mur : deux rangées d'étals adossés, un îlot central et deux allées de circulation, le tout couvert d'un gr"},{"n":"Temple de jungle — sanctuaire à gradins","c":"Plan","p":"plans.html","a":"temple-jungle","d":"Une pyramide à degrés en pierre moussue, deux terrasses ceintes de lianes, un escalier axial et une cella fermée qui abrite l'autel. Se cons"},{"n":"Camp de mineurs à l'entrée d'une mine","c":"Plan","p":"plans.html","a":"camp-mineurs","d":"La tête de puits : une terrasse taillée dans la falaise, deux cabanes, une batterie de fours et une voie de wagonnets qui sort directement d"},{"n":"Fonderie automatique (super smelter)","c":"Usine","p":"usines.html","a":"four-auto","d":"Un four alimenté par trois entonnoirs : un pour le minerai, un pour le charbon, un pour la sortie. Vous déposez 3 piles de fer brut et vous "},{"n":"Ferme à canne à sucre (observateur + piston)","c":"Usine","p":"usines.html","a":"canne","d":"La ferme entièrement automatique la plus simple du jeu. La canne pousse jusqu'au 3ᵉ bloc, un observateur détecte la pousse et un piston la c"},{"n":"Ferme à bambou / kelp (carburant illimité)","c":"Usine","p":"usines.html","a":"bambou","d":"Même principe que la canne à sucre, mais le bambou pousse jusqu'à 16 blocs de haut et très vite. Combiné à un fabricateur, il produit des bl"},{"n":"Ferme à poulets auto-cuiseur","c":"Usine","p":"usines.html","a":"poulet","d":"Les poulets pondent, les œufs sont ramassés par un entonnoir et relancés par un distributeur : les poussins éclosent, grandissent, et la lav"},{"n":"Ferme à blé automatique (villageois fermier)","c":"Usine","p":"usines.html","a":"ble-auto","d":"Un villageois fermier enfermé au-dessus de la parcelle sème, récolte et lance les surplus. Un entonnoir capte tout ce qu'il laisse tomber. Z"},{"n":"Ferme à melons / citrouilles","c":"Usine","p":"usines.html","a":"melon","d":"La tige pousse et fait apparaître un melon ou une citrouille sur une case adjacente. Un observateur détecte l'apparition, un piston le casse"},{"n":"Ferme à fer (golems de village)","c":"Usine","p":"usines.html","a":"fer","d":"Trois villageois effrayés par un zombie appellent un golem de fer, qui apparaît dans une zone de spawn contrôlée puis tombe dans un broyeur."},{"n":"Ferme à XP sur générateur de donjon","c":"Usine","p":"usines.html","a":"mob-spawner","d":"La première ferme à mobs de toute partie : on récupère un générateur de zombies ou de squelettes trouvé en donjon et on canalise ses mobs ve"},{"n":"Tour à mobs générale (dark room)","c":"Usine","p":"usines.html","a":"mobfarm","d":"Des plateformes obscures suspendues au-dessus de l'océan ou du vide : tous les monstres du Surworld y apparaissent, sont convoyés par l'eau "},{"n":"Ferme à creepers (poudre à canon)","c":"Usine","p":"usines.html","a":"creeper","d":"Une tour à mobs dont le plafond est bas de 2 blocs seulement : seuls les creepers et les araignées passent. Avec des chats à proximité, on é"},{"n":"Ferme à or (zombies-piglins, Nether)","c":"Usine","p":"usines.html","a":"or","d":"Dans une vallée de sable des âmes ou sur une plateforme au-dessus du vide du Nether, les zombies-piglins apparaissent en masse. Convoyés et "},{"n":"Ferme à squelettes wither (crânes)","c":"Usine","p":"usines.html","a":"wither-skel","d":"Aménagement d'un carrefour de forteresse du Nether : on ne garde que les briques du Nether comme surface d'apparition, ce qui rend les squel"},{"n":"Ferme à raids (totems & émeraudes)","c":"Usine","p":"usines.html","a":"raid","d":"Un village artificiel dont le seul villageois déclenche des raids en boucle. Chaque raid rend des totems d'immortalité, des émeraudes et un "},{"n":"Ferme à endermen (XP maximale)","c":"Usine","p":"usines.html","a":"enderman","d":"Dans les plaines de l'End, seuls les endermen apparaissent. Une plateforme au-dessus du vide avec un endermite en appât : c'est la ferme d'X"},{"n":"Ferme à gardiens (monument océanique)","c":"Usine","p":"usines.html","a":"guardian","d":"Le monument océanique est la seule zone où les gardiens apparaissent, y compris à travers l'eau. Vidé de son eau, il devient la ferme la plu"},{"n":"Trieur automatique multi-lignes","c":"Usine","p":"usines.html","a":"trieur","d":"Le système nerveux d'une base : toutes vos fermes déversent dans une ligne d'entonnoirs, et chaque objet finit dans son coffre dédié, sans i"},{"n":"Compacteur automatique (fabricateur)","c":"Usine","p":"usines.html","a":"compacteur","d":"Le fabricateur (crafter) de la 1.21 transforme automatiquement 9 lingots en 1 bloc. Placé en amont du stockage, il divise par neuf le volume"},{"n":"Générateur de pierre automatique","c":"Usine","p":"usines.html","a":"cobble","d":"Lave + eau = pierre, à l'infini. Un piston casse le bloc formé, un entonnoir le collecte : la ressource de construction illimitée, pour les "},{"n":"Hall de commerce (villageois)","c":"Usine","p":"usines.html","a":"trading","d":"La véritable « usine à ressources » du jeu : des villageois enfermés en cellules individuelles, chacun avec son bloc de métier. Enchantement"},{"n":"Ascenseur à bulles (eau + âme du sable)","c":"Usine","p":"usines.html","a":"ascenseur","d":"Le moyen le plus rapide et le moins cher de monter ou descendre de 100 blocs. Deux colonnes côte à côte : une pour monter, une pour descendr"},{"n":"Réseau de transport du Nether","c":"Usine","p":"usines.html","a":"nether-hub","d":"Ce n'est pas une machine mais l'infrastructure la plus rentable du jeu : 1 bloc parcouru dans le Nether = 8 blocs en surface. Un réseau de t"},{"n":"Ferme à miel et rayons de miel","c":"Usine","p":"usines.html","a":"miel","d":"Un dispensateur avec une bouteille ou une cisaille récolte automatiquement la ruche quand elle atteint le niveau de miel 5, détecté par un c"},{"n":"Ferme à arbres semi-automatique","c":"Usine","p":"usines.html","a":"arbre","d":"Bois, pousses et pommes en continu. La version simple utilise la poudre d'os et une hache ; la version automatique utilise du TNT ou une mac"},{"n":"Ferme d'améthyste","c":"Usine","p":"usines.html","a":"amethyste","d":"Les bourgeons d'améthyste repoussent indéfiniment sur le bloc d'améthyste en gemme. Un piston les récolte au stade final, un canal d'eau les"},{"n":"Ferme à XP au catalyseur de sculk","c":"Usine","p":"usines.html","a":"sculk-xp","d":"Un catalyseur de sculk placé sous une zone de mise à mort convertit les morts en blocs de sculk. On les mine ensuite pour récupérer une XP c"},{"n":"Ferme à tridents (noyés de rivière)","c":"Usine","p":"usines.html","a":"trident-noyes","d":"Une plateforme d'eau totalement obscure posée dans un biome de rivière : les noyés qui y apparaissent naturellement sont les seuls du jeu à "},{"n":"Ferme à slimes (chunk à slime)","c":"Usine","p":"usines.html","a":"slime-chunk","d":"Les slimes n'apparaissent que dans certains chunks tirés au sort par la graine du monde (environ 1 sur 10), sous Y = 40, quelle que soit la "},{"n":"Ferme à shulkers (duplication en cité de l'End)","c":"Usine","p":"usines.html","a":"shulker-dup","d":"Quand le projectile d'un shulker touche un autre shulker, celui-ci a une chance d'en engendrer un nouveau : c'est la seule duplication de mo"},{"n":"Ferme à lumigrenouilles (grenouilles + cubes de magma)","c":"Usine","p":"usines.html","a":"froglight","d":"Une grenouille qui avale un PETIT cube de magma le transforme en bloc de lumigrenouille. On monte donc une plateforme à cubes de magma dans "},{"n":"Carrière à sable et gravier (pistons + rails)","c":"Usine","p":"usines.html","a":"sable-gravier","d":"Le sable et le gravier tombent dès qu'on retire leur support. Une rangée de pistons collants arrache la base d'une dune, toute la colonne s'"},{"n":"Ferme à obsidienne (lave renouvelable)","c":"Usine","p":"usines.html","a":"obsidienne-auto","d":"Une stalactite pointue suspendue sous une source de lave remplit un chaudron sans jamais consommer la source : la lave devient renouvelable."},{"n":"Reproduction et tri automatiques de villageois","c":"Usine","p":"usines.html","a":"villageois-repro","d":"Deux couples de villageois nourris automatiquement se reproduisent en boucle. Les bébés, deux fois moins hauts que les adultes, s'échappent "},{"n":"Ferme à œufs de tortue et écailles","c":"Usine","p":"usines.html","a":"tortue-ecailles","d":"Une tortue ne pond que sur le sable de la plage où elle est née. Les œufs éclosent la nuit, les bébés s'échappent par un couloir d'un bloc d"},{"n":"Ferme à laine automatique (distributeur à cisailles)","c":"Usine","p":"usines.html","a":"mouton-laine","d":"Un mouton posé sur un bloc d'herbe finit toujours par la brouter : le bloc devient de la terre, un observateur détecte le changement et décl"},{"n":"Ferme à cactus (colorant vert automatique)","c":"Usine","p":"usines.html","a":"cactus-vert","d":"Un cactus se casse tout seul dès qu'un bloc touche son flanc. Il suffit donc d'aligner des colonnes de cactus autour d'une rangée de blocs :"},{"n":"Ferme à champignons géants","c":"Usine","p":"usines.html","a":"champignons-geants","d":"Une salle obscure au sol de mycélium où des distributeurs projettent de la poudre d'os sur des champignons plantés en damier. Chaque pied de"},{"n":"Ferme à œufs dédiée (sans cuisson)","c":"Usine","p":"usines.html","a":"oeufs","d":"Une volière vitrée dont le plancher est entièrement en entonnoirs : les poules restent vivantes, pondent toutes les 5 à 10 minutes et les œu"},{"n":"Ferme à pommes et bûches de chêne noir","c":"Usine","p":"usines.html","a":"pommes-chene-noir","d":"Le chêne noir pousse en bosquets de 2 × 2 et laisse toujours un tronc épais et une canopée large : c'est le seul arbre qui rentabilise vraim"},{"n":"Ferme à glace bleue (bassin de gel + compactage)","c":"Usine","p":"usines.html","a":"glace-bleue","d":"En biome froid, une lame d'eau d'un bloc de large gèle en quelques dizaines de secondes. On récolte au Toucher de soie depuis une passerelle"},{"n":"Ferme à neige et à poudre de neige","c":"Usine","p":"usines.html","a":"neige-poudreuse","d":"Un golem de neige laisse une couche de neige partout où il passe. Enfermé dans une cellule d'un bloc au-dessus d'un rail, il neige sur place"},{"n":"Ferme à charbon de bois (bosquet + fours en boucle)","c":"Usine","p":"usines.html","a":"charbon-de-bois","d":"Un bosquet ordonné alimente une batterie de fours qui transforment les bûches en charbon de bois. Une partie de la production est renvoyée d"},{"n":"Rangement à double tri (objets et blocs compactés)","c":"Usine","p":"usines.html","a":"tri-double","d":"Un mur de tri à deux étages : la ligne haute trie les objets bruts, le trop-plein passe par des fabricateurs qui compactent 9 unités en 1 bl"}];
